searchData={"items":[{"type":"task","title":"mix credence","doc":"Credence finds code that works but isn't written the Elixir way (a list\nbuilt only to be summed, a zip then a map) and rewrites it.\n`mix credence` fixes each file it finds something in, in place, with\n`Credence.fix/2`, and lists what it couldn't fix; `mix credence --check`\n(precommit and CI) changes nothing and fails listing what it finds.\n\nOnly the rules that hold for any Unicode text run (`config :credence,\nassumptions: :strict`, in dev and test): sound names and tags aren't\nplain ASCII.","ref":"Mix.Tasks.Credence.html"},{"type":"module","title":"Soundboard","doc":"Soundboard keeps the contexts that define your domain\nand business logic.\n\nContexts are also responsible for managing your data, regardless\nif it comes from the database, an external API or others.","ref":"Soundboard.html"},{"type":"module","title":"Soundboard.Accounts","doc":"Accounts boundary helpers used by web and runtime code.","ref":"Soundboard.Accounts.html"},{"type":"function","title":"Soundboard.Accounts.avatars_by_usernames/1","doc":"","ref":"Soundboard.Accounts.html#avatars_by_usernames/1"},{"type":"function","title":"Soundboard.Accounts.get_user/1","doc":"","ref":"Soundboard.Accounts.html#get_user/1"},{"type":"module","title":"Soundboard.Accounts.ApiToken","doc":"API access token bound to a user.\n\nThe token hash is used for verification. The plaintext token is shown once\nat creation time and is never persisted.","ref":"Soundboard.Accounts.ApiToken.html"},{"type":"type","title":"Soundboard.Accounts.ApiToken.t/0","doc":"","ref":"Soundboard.Accounts.ApiToken.html#t:t/0"},{"type":"function","title":"Soundboard.Accounts.ApiToken.changeset/2","doc":"","ref":"Soundboard.Accounts.ApiToken.html#changeset/2"},{"type":"module","title":"Soundboard.Accounts.ApiTokens","doc":"Context for managing API tokens bound to users.","ref":"Soundboard.Accounts.ApiTokens.html"},{"type":"type","title":"Soundboard.Accounts.ApiTokens.revoke_result/0","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#t:revoke_result/0"},{"type":"type","title":"Soundboard.Accounts.ApiTokens.verify_error/0","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#t:verify_error/0"},{"type":"type","title":"Soundboard.Accounts.ApiTokens.verify_result/0","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#t:verify_result/0"},{"type":"function","title":"Soundboard.Accounts.ApiTokens.generate_token/2","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#generate_token/2"},{"type":"function","title":"Soundboard.Accounts.ApiTokens.list_tokens/1","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#list_tokens/1"},{"type":"function","title":"Soundboard.Accounts.ApiTokens.revoke_token/2","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#revoke_token/2"},{"type":"function","title":"Soundboard.Accounts.ApiTokens.verify_token/1","doc":"","ref":"Soundboard.Accounts.ApiTokens.html#verify_token/1"},{"type":"module","title":"Soundboard.Accounts.User","doc":"The User module.","ref":"Soundboard.Accounts.User.html"},{"type":"type","title":"Soundboard.Accounts.User.t/0","doc":"","ref":"Soundboard.Accounts.User.html#t:t/0"},{"type":"function","title":"Soundboard.Accounts.User.changeset/2","doc":"","ref":"Soundboard.Accounts.User.html#changeset/2"},{"type":"function","title":"Soundboard.Accounts.User.discord_params/3","doc":"The params `changeset/2` accepts from a Discord identity.","ref":"Soundboard.Accounts.User.html#discord_params/3"},{"type":"module","title":"Soundboard.AudioPlayer","doc":"Facade over the per-guild audio player servers.\n\nOne `Soundboard.AudioPlayer.Server` process exists per guild. All functions\nroute by `guild_id`; when omitted, the default guild is used so existing\nsingle-guild deployments behave exactly as before.","ref":"Soundboard.AudioPlayer.html"},{"type":"function","title":"Soundboard.AudioPlayer.current_voice_channel/1","doc":"","ref":"Soundboard.AudioPlayer.html#current_voice_channel/1"},{"type":"function","title":"Soundboard.AudioPlayer.ensure_started/1","doc":"Starts the player for `guild_id` if not already running. Returns its pid.","ref":"Soundboard.AudioPlayer.html#ensure_started/1"},{"type":"function","title":"Soundboard.AudioPlayer.invalidate_cache/2","doc":"Removes any cached metadata for `filename` in `guild_id` so future plays use\nfresh data.","ref":"Soundboard.AudioPlayer.html#invalidate_cache/2"},{"type":"function","title":"Soundboard.AudioPlayer.last_user_left/1","doc":"","ref":"Soundboard.AudioPlayer.html#last_user_left/1"},{"type":"function","title":"Soundboard.AudioPlayer.play_sound/3","doc":"","ref":"Soundboard.AudioPlayer.html#play_sound/3"},{"type":"function","title":"Soundboard.AudioPlayer.playback_finished/1","doc":"","ref":"Soundboard.AudioPlayer.html#playback_finished/1"},{"type":"function","title":"Soundboard.AudioPlayer.server_pid/1","doc":"Pid of the player server for `guild_id`, if running.","ref":"Soundboard.AudioPlayer.html#server_pid/1"},{"type":"function","title":"Soundboard.AudioPlayer.set_voice_channel/2","doc":"","ref":"Soundboard.AudioPlayer.html#set_voice_channel/2"},{"type":"function","title":"Soundboard.AudioPlayer.stop_sound/1","doc":"","ref":"Soundboard.AudioPlayer.html#stop_sound/1"},{"type":"function","title":"Soundboard.AudioPlayer.user_joined_channel/1","doc":"","ref":"Soundboard.AudioPlayer.html#user_joined_channel/1"},{"type":"module","title":"Soundboard.AudioPlayer.Server","doc":"Per-guild audio playback coordinator.\n\nOne Server process exists per guild that has audio activity, registered in\n`Soundboard.AudioPlayer.Registry` under the guild id and supervised by\n`Soundboard.AudioPlayer.Supervisor`. All state (voice channel, queue,\nplayback) is scoped to a single guild, so multiple tenants cannot interfere\nwith each other.","ref":"Soundboard.AudioPlayer.Server.html"},{"type":"function","title":"Soundboard.AudioPlayer.Server.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"Soundboard.AudioPlayer.Server.html#child_spec/1"},{"type":"function","title":"Soundboard.AudioPlayer.Server.start_link/1","doc":"","ref":"Soundboard.AudioPlayer.Server.html#start_link/1"},{"type":"function","title":"Soundboard.AudioPlayer.Server.via/1","doc":"","ref":"Soundboard.AudioPlayer.Server.html#via/1"},{"type":"module","title":"Soundboard.AudioPlayer.State","doc":"The state of a per-guild audio player server.","ref":"Soundboard.AudioPlayer.State.html"},{"type":"type","title":"Soundboard.AudioPlayer.State.t/0","doc":"","ref":"Soundboard.AudioPlayer.State.html#t:t/0"},{"type":"module","title":"Soundboard.Billing","doc":"Stripe-backed storage subscriptions for guild tenants.\n\nDormancy: billing is dormant unless `STRIPE_SECRET_KEY` is set. Everything in\nthis module gates on `configured?/0`; when Stripe is unconfigured the app\nbehaves exactly as it did before billing existed (provisioning happens on\nguild switch, every tenant gets the platform default storage cap).\n\nPlan catalog (price ids come from env, see `config/runtime.exs`):\n\n| Tier   | Cap    | Monthly | Yearly |\n|--------|--------|---------|--------|\n| Pro    | 1 GB   | $4      | $36    |\n| Studio | 5 GB   | $10     | $96    |\n\nThe price-id -> cap mapping lives here (`plan_cap/1`) and is the single\nsource of truth; the webhook is the only hosted provisioning path (it\nprovisions the tenant row via `Tenants.get_or_create_guild/2` and writes\n`max_storage_bytes`), so a guild can never get a paid cap without a Stripe\npayment event.","ref":"Soundboard.Billing.html"},{"type":"module","title":"Idempotency - Soundboard.Billing","doc":"Stripe retries webhook deliveries until they are acked, so events must be\nprocessed at most once. Processed event ids are remembered in a public ETS\ntable (`:billing_processed_events`). Tradeoff: ETS is in-memory, so a node\nrestart forgets the set and Stripe retries arriving across a restart could\nreplay an event. That is safe here because every handler is an absolute\nwrite (set the cap to the plan's cap, not an increment), so replays are\nno-ops; the ETS set just avoids redundant work in the common case.\n\nThe guild's subscription (its id and line item id) is cached in memory too.\nAfter a restart it is recovered from Stripe: by the remembered customer\nwhen there is one, otherwise by the `guild_id` metadata on the\nsubscription. Stripe API results are structs and webhook payloads plain\nmaps; `field/2` reads either.","ref":"Soundboard.Billing.html#module-idempotency"},{"type":"module","title":"Ordering and status - Soundboard.Billing","doc":"Stripe does not deliver events in order. Only an `active` or `trialing`\nsubscription carries its plan's cap; any other status (past_due, unpaid,\ncanceled, incomplete) leaves the guild at cap 0. The `created` time of the\nlast event applied to each subscription is remembered (in memory, like the\nrest), and an older event for that subscription is acknowledged without\nbeing applied, so a late `customer.subscription.updated` cannot undo a\ndeletion. The limitation: that memory does not survive a restart, so an\nout-of-order event arriving across a restart is still applied.\n\nStripe customer ids seen on events are kept in a second ETS table\n(`:billing_stripe_customers`) so the customer portal can be opened without\na `stripe_customer_id` column on `guilds`. Also in-memory: after a restart\nthe portal is unavailable until the next event repopulates it.","ref":"Soundboard.Billing.html#module-ordering-and-status"},{"type":"function","title":"Soundboard.Billing.cancel_subscription/1","doc":"Flags the guild's subscription to cancel at the end of the current billing\nperiod (Stripe keeps it active until then; customer.subscription.deleted\nlater reverts the guild to no plan).","ref":"Soundboard.Billing.html#cancel_subscription/1"},{"type":"function","title":"Soundboard.Billing.change_subscription_price/2","doc":"Moves the guild's live subscription to another price (tier or interval\nchange). Stripe prorates automatically; the subscription.updated webhook\napplies the new cap.","ref":"Soundboard.Billing.html#change_subscription_price/2"},{"type":"function","title":"Soundboard.Billing.config/0","doc":"Billing configuration (set in `config/runtime.exs` from STRIPE_* env vars).","ref":"Soundboard.Billing.html#config/0"},{"type":"function","title":"Soundboard.Billing.configured?/0","doc":"Whether Stripe billing is active (STRIPE_SECRET_KEY present).","ref":"Soundboard.Billing.html#configured?/0"},{"type":"function","title":"Soundboard.Billing.create_checkout_session/4","doc":"Creates a Stripe Checkout Session for `guild_id` at `price_id`.\n\nThe session carries the guild id in `client_reference_id` (Stripe's\nreconciliation key) and in metadata (read back by the webhook). The price id\nis also mirrored into metadata because checkout session payloads do not\ninclude line items unless they are expanded.\n\nStripe returns the user to `opts[:base_url]` when given (the host they came\nin on, which behind a proxy or on a local test domain differs from\nPHX_HOST), otherwise to the configured URL.\n\nReturns `{:ok, %{id: id, url: url}}` or `{:error, :not_configured |\n:invalid_price | term()}`.","ref":"Soundboard.Billing.html#create_checkout_session/4"},{"type":"function","title":"Soundboard.Billing.create_portal_session/2","doc":"Creates a Stripe customer portal session for the guild's customer. Requires\nthe guild to have a customer id already seen on a billing webhook event\n(kept in-memory; see the module doc).","ref":"Soundboard.Billing.html#create_portal_session/2"},{"type":"function","title":"Soundboard.Billing.current_price_id_for_guild/1","doc":"The price id last seen on the guild's subscription, or nil.","ref":"Soundboard.Billing.html#current_price_id_for_guild/1"},{"type":"function","title":"Soundboard.Billing.customer_id_for_guild/1","doc":"The Stripe customer id last seen for a guild, or nil.","ref":"Soundboard.Billing.html#customer_id_for_guild/1"},{"type":"function","title":"Soundboard.Billing.format_bytes/1","doc":"Bytes formatted for display: MB up to 1000 MB, then GB.","ref":"Soundboard.Billing.html#format_bytes/1"},{"type":"function","title":"Soundboard.Billing.format_price/1","doc":"Cents to a display price like \"$3.99\".","ref":"Soundboard.Billing.html#format_price/1"},{"type":"function","title":"Soundboard.Billing.handle_webhook/2","doc":"Verifies the Stripe signature header, then dispatches the event.\n\nThe `Stripe-Signature` header (`t=...,v1=...`) is checked locally with\nHMAC-SHA256 over `\" . \"` and a five-minute timestamp tolerance,\nrather than through `Stripe.Webhook.construct_event/3`.\n\nReturns `{:ok, event_id | :duplicate}` on success (both ack the delivery),\n`{:error, :invalid_signature}` for tampered/foreign payloads, or\n`{:error, term()}` for malformed payloads / handler failures.","ref":"Soundboard.Billing.html#handle_webhook/2"},{"type":"function","title":"Soundboard.Billing.interval_for_price/1","doc":"Maps a known plan price id to its billing interval (:monthly/:yearly), or nil.","ref":"Soundboard.Billing.html#interval_for_price/1"},{"type":"function","title":"Soundboard.Billing.known_subscription?/1","doc":"Whether the guild has a Stripe subscription we can act on. Falls back to a\nStripe lookup by remembered customer when in-memory state is missing (e.g.\nafter a restart, or events processed by older code).","ref":"Soundboard.Billing.html#known_subscription?/1"},{"type":"function","title":"Soundboard.Billing.plan_cap/1","doc":"The storage cap in bytes for a Stripe price id, or nil when unknown.","ref":"Soundboard.Billing.html#plan_cap/1"},{"type":"function","title":"Soundboard.Billing.plan_for_cap/1","doc":"The plan a storage cap belongs to: :studio, :pro, or nil. A cap that\nmatches no plan exactly (a legacy or self-hosted row) has none: the webhook\nonly ever writes exact plan caps.","ref":"Soundboard.Billing.html#plan_for_cap/1"},{"type":"function","title":"Soundboard.Billing.plan_label/1","doc":"Human plan name for a cap value.","ref":"Soundboard.Billing.html#plan_label/1"},{"type":"function","title":"Soundboard.Billing.price_cap_map/0","doc":"Maps every configured Stripe price id to its storage cap in bytes. This is\nthe single source of truth for the price -> plan mapping.","ref":"Soundboard.Billing.html#price_cap_map/0"},{"type":"function","title":"Soundboard.Billing.reset_memory/0","doc":"Clears in-memory billing state (processed events, customer ids). Test and\nops helper; production state is intentionally reconstructible (see the\nmodule doc on idempotency).","ref":"Soundboard.Billing.html#reset_memory/0"},{"type":"function","title":"Soundboard.Billing.subscription_active?/1","doc":"Whether a guild has an active subscription: a tenant row whose storage cap\nexactly matches a paid plan (the webhook only writes exact plan caps).\nRows with cap 0, legacy/default caps, or no row at all count as unpaid —\non hosted there is no free tier; self-hosted never reaches this check\nbecause the paywall gate short-circuits when billing is dormant.","ref":"Soundboard.Billing.html#subscription_active?/1"},{"type":"function","title":"Soundboard.Billing.tiers/0","doc":"Plan catalog entries for display (name, cap, amounts, configured price ids).","ref":"Soundboard.Billing.html#tiers/0"},{"type":"function","title":"Soundboard.Billing.valid_price?/1","doc":"Whether the price id belongs to the configured plan catalog.","ref":"Soundboard.Billing.html#valid_price?/1"},{"type":"module","title":"Soundboard.Billing.SubscriptionSnapshot","doc":"The guild's live Stripe subscription state cached in memory between\nwebhooks: the subscription id, its line item id, and the price id.","ref":"Soundboard.Billing.SubscriptionSnapshot.html"},{"type":"type","title":"Soundboard.Billing.SubscriptionSnapshot.t/0","doc":"","ref":"Soundboard.Billing.SubscriptionSnapshot.html#t:t/0"},{"type":"module","title":"Soundboard.Boundary","doc":"The exception types that can realistically escape across a process or API\nboundary here: the Discord gateway (EDA), voice, HTTP, the file system and\nSQLite. Code rescues `e in @boundary_exceptions` rather than everything;\nexits and throws are caught separately.","ref":"Soundboard.Boundary.html"},{"type":"function","title":"Soundboard.Boundary.exceptions/0","doc":"","ref":"Soundboard.Boundary.html#exceptions/0"},{"type":"module","title":"Soundboard.Discord.Handler","doc":"Handles the Discord events.\n\nA deployment with no guild configured (no `:default_guild_id` or\n`:required_guild_id`) discovers its guild once READY arrives: guilds stream\ninto the cache after READY, so it polls briefly for the bot's sole guild and\nrepoints rows migrated as \"default\" (`Tenants.reconcile_default_guild/0`).","ref":"Soundboard.Discord.Handler.html"},{"type":"function","title":"Soundboard.Discord.Handler.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"Soundboard.Discord.Handler.html#child_spec/1"},{"type":"function","title":"Soundboard.Discord.Handler.dispatch_event/1","doc":"","ref":"Soundboard.Discord.Handler.html#dispatch_event/1"},{"type":"function","title":"Soundboard.Discord.Handler.handle_event/1","doc":"","ref":"Soundboard.Discord.Handler.html#handle_event/1"},{"type":"function","title":"Soundboard.Discord.Handler.init/0","doc":"","ref":"Soundboard.Discord.Handler.html#init/0"},{"type":"function","title":"Soundboard.Discord.Handler.start_link/1","doc":"","ref":"Soundboard.Discord.Handler.html#start_link/1"},{"type":"module","title":"Soundboard.Discord.Handler.SoundEffects","doc":"Join and leave sounds. A join is a voice state with no tracked previous one\n(a first join, or state lost on restart) or one after a disconnect; a\nchannel switch or a mute/deafen update is not.","ref":"Soundboard.Discord.Handler.SoundEffects.html"},{"type":"function","title":"Soundboard.Discord.Handler.SoundEffects.handle_join/4","doc":"","ref":"Soundboard.Discord.Handler.SoundEffects.html#handle_join/4"},{"type":"function","title":"Soundboard.Discord.Handler.SoundEffects.handle_leave/2","doc":"","ref":"Soundboard.Discord.Handler.SoundEffects.html#handle_leave/2"},{"type":"module","title":"Soundboard.Discord.Handler.State","doc":"Handles the state of the Discord handler.","ref":"Soundboard.Discord.Handler.State.html"},{"type":"function","title":"Soundboard.Discord.Handler.State.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"Soundboard.Discord.Handler.State.html#child_spec/1"},{"type":"function","title":"Soundboard.Discord.Handler.State.get_state/1","doc":"","ref":"Soundboard.Discord.Handler.State.html#get_state/1"},{"type":"function","title":"Soundboard.Discord.Handler.State.init/1","doc":"Callback implementation for  GenServer.init/1 .","ref":"Soundboard.Discord.Handler.State.html#init/1"},{"type":"function","title":"Soundboard.Discord.Handler.State.start_link/1","doc":"","ref":"Soundboard.Discord.Handler.State.html#start_link/1"},{"type":"function","title":"Soundboard.Discord.Handler.State.update_state/3","doc":"","ref":"Soundboard.Discord.Handler.State.html#update_state/3"},{"type":"module","title":"Soundboard.Discord.InviteURL","doc":"Builds the bot invite URL used by the onboarding flow.\n\nThe shared bot only needs to see the channels it is invited to, connect to\nvoice, and speak. The permissions integer is pinned by the onboarding page test\n(`SoundboardWeb.OnboardingTest`) so the scope cannot drift silently.","ref":"Soundboard.Discord.InviteURL.html"},{"type":"function","title":"Soundboard.Discord.InviteURL.build/1","doc":"","ref":"Soundboard.Discord.InviteURL.html#build/1"},{"type":"module","title":"Soundboard.Favorites","doc":"The Favorites module.","ref":"Soundboard.Favorites.html"},{"type":"type","title":"Soundboard.Favorites.favorite_result/0","doc":"","ref":"Soundboard.Favorites.html#t:favorite_result/0"},{"type":"function","title":"Soundboard.Favorites.error_message/1","doc":"","ref":"Soundboard.Favorites.html#error_message/1"},{"type":"function","title":"Soundboard.Favorites.list_favorite_sounds_with_tags/2","doc":"","ref":"Soundboard.Favorites.html#list_favorite_sounds_with_tags/2"},{"type":"function","title":"Soundboard.Favorites.list_favorites/2","doc":"","ref":"Soundboard.Favorites.html#list_favorites/2"},{"type":"function","title":"Soundboard.Favorites.max_favorites/0","doc":"","ref":"Soundboard.Favorites.html#max_favorites/0"},{"type":"function","title":"Soundboard.Favorites.toggle_favorite/3","doc":"","ref":"Soundboard.Favorites.html#toggle_favorite/3"},{"type":"module","title":"Soundboard.Favorites.Favorite","doc":"The Favorite module.","ref":"Soundboard.Favorites.Favorite.html"},{"type":"type","title":"Soundboard.Favorites.Favorite.t/0","doc":"","ref":"Soundboard.Favorites.Favorite.html#t:t/0"},{"type":"function","title":"Soundboard.Favorites.Favorite.changeset/2","doc":"","ref":"Soundboard.Favorites.Favorite.html#changeset/2"},{"type":"module","title":"Soundboard.PublicURL","doc":"Shared helper for the application's externally visible base URL.\n\nWeb and Discord-facing features use this so URL generation follows one\napplication-level contract instead of reaching into endpoint config details in\nmultiple places.","ref":"Soundboard.PublicURL.html"},{"type":"function","title":"Soundboard.PublicURL.current/0","doc":"","ref":"Soundboard.PublicURL.html#current/0"},{"type":"function","title":"Soundboard.PublicURL.from_uri_or_current/1","doc":"","ref":"Soundboard.PublicURL.html#from_uri_or_current/1"},{"type":"module","title":"Soundboard.Repo","doc":"","ref":"Soundboard.Repo.html"},{"type":"function","title":"Soundboard.Repo.aggregate/3","doc":"Callback implementation for  Ecto.Repo.aggregate/3 .","ref":"Soundboard.Repo.html#aggregate/3"},{"type":"function","title":"Soundboard.Repo.aggregate/4","doc":"Callback implementation for  Ecto.Repo.aggregate/4 .","ref":"Soundboard.Repo.html#aggregate/4"},{"type":"function","title":"Soundboard.Repo.all/2","doc":"Callback implementation for  Ecto.Repo.all/2 .","ref":"Soundboard.Repo.html#all/2"},{"type":"function","title":"Soundboard.Repo.all_by/3","doc":"Callback implementation for  Ecto.Repo.all_by/3 .","ref":"Soundboard.Repo.html#all_by/3"},{"type":"function","title":"Soundboard.Repo.checked_out?/0","doc":"Callback implementation for  Ecto.Repo.checked_out?/0 .","ref":"Soundboard.Repo.html#checked_out?/0"},{"type":"function","title":"Soundboard.Repo.checkout/2","doc":"Callback implementation for  Ecto.Repo.checkout/2 .","ref":"Soundboard.Repo.html#checkout/2"},{"type":"function","title":"Soundboard.Repo.child_spec/1","doc":"","ref":"Soundboard.Repo.html#child_spec/1"},{"type":"function","title":"Soundboard.Repo.config/0","doc":"Callback implementation for  Ecto.Repo.config/0 .","ref":"Soundboard.Repo.html#config/0"},{"type":"function","title":"Soundboard.Repo.default_options/1","doc":"Callback implementation for  Ecto.Repo.default_options/1 .","ref":"Soundboard.Repo.html#default_options/1"},{"type":"function","title":"Soundboard.Repo.delete/2","doc":"Callback implementation for  Ecto.Repo.delete/2 .","ref":"Soundboard.Repo.html#delete/2"},{"type":"function","title":"Soundboard.Repo.delete!/2","doc":"Callback implementation for  Ecto.Repo.delete!/2 .","ref":"Soundboard.Repo.html#delete!/2"},{"type":"function","title":"Soundboard.Repo.delete_all/2","doc":"Callback implementation for  Ecto.Repo.delete_all/2 .","ref":"Soundboard.Repo.html#delete_all/2"},{"type":"function","title":"Soundboard.Repo.disconnect_all/2","doc":"Forces all connections in the repo pool to disconnect within the given interval.\n\nOnce this function is called, the pool will disconnect all of its connections\nas they are checked in or as they are pinged. Checked in and idle connections\nwill be randomly disconnected within the given time interval.\n\nIf the connection has a backoff configured (which is the case by default),\ndisconnecting means an attempt at a new connection will be done immediately\nafter, without starting a new process for each connection. However, if backoff\nhas been disabled, the connection process will terminate. In such cases,\ndisconnecting all connections may cause the pool supervisor to restart\ndepending on the max_restarts/max_seconds configuration of the pool,\nso you will want to set those carefully.\n\nIf you need connections to be restarted periodically, set the `:max_lifetime`\noption in your repository configuration instead.","ref":"Soundboard.Repo.html#disconnect_all/2"},{"type":"function","title":"Soundboard.Repo.exists?/2","doc":"Callback implementation for  Ecto.Repo.exists?/2 .","ref":"Soundboard.Repo.html#exists?/2"},{"type":"function","title":"Soundboard.Repo.explain/3","doc":"Executes an EXPLAIN statement or similar for the given query according to its kind and the\nadapter in the given repository.","ref":"Soundboard.Repo.html#explain/3"},{"type":"function","title":"Examples - Soundboard.Repo.explain/3","doc":"# Postgres\n    iex> MyRepo.explain(:all, Post)\n    \"Seq Scan on posts p0  (cost=0.00..12.12 rows=1 width=443)\"\n\n    iex> Ecto.Adapters.SQL.explain(Repo, :all, Post)\n    \"Seq Scan on posts p0  (cost=0.00..12.12 rows=1 width=443)\"\n\n    # MySQL\n    iex> MyRepo.explain(:all, from(p in Post, where: p.title == \"title\")) |> IO.puts()\n    +----+-------------+-------+------------+------+---------------+------+---------+------+------+----------+-------------+\n    | id | select_type | table | partitions | type | possible_keys | key  | key_len | ref  | rows | filtered | Extra       |\n    +----+-------------+-------+------------+------+---------------+------+---------+------+------+----------+-------------+\n    |  1 | SIMPLE      | p0    | NULL       | ALL  | NULL          | NULL | NULL    | NULL |    1 |    100.0 | Using where |\n    +----+-------------+-------+------------+------+---------------+------+---------+------+------+----------+-------------+\n\n    # Shared opts\n    iex> MyRepo.explain(:all, Post, analyze: true, timeout: 20_000)\n    \"Seq Scan on posts p0  (cost=0.00..11.70 rows=170 width=443) (actual time=0.013..0.013 rows=0 loops=1)\\nPlanning Time: 0.031 ms\\nExecution Time: 0.021 ms\"\n\nIt's safe to execute it for updates and deletes, no data change will be committed:\n\n    iex> MyRepo.explain(Repo, :update_all, from(p in Post, update: [set: [title: \"new title\"]]))\n    \"Update on posts p0  (cost=0.00..11.70 rows=170 width=449)\\n  ->  Seq Scan on posts p0  (cost=0.00..11.70 rows=170 width=449)\"\n\nThis function is also available under the repository with name `explain`:\n\n    iex> MyRepo.explain(:all, from(p in Post, where: p.title == \"title\"))\n    \"Seq Scan on posts p0  (cost=0.00..12.12 rows=1 width=443)\\n  Filter: ((title)::text = 'title'::text)\"","ref":"Soundboard.Repo.html#explain/3-examples"},{"type":"function","title":"Options - Soundboard.Repo.explain/3","doc":"Built-in adapters support passing `opts` to the EXPLAIN statement according to the following:\n\nAdapter          | Supported opts\n---------------- | --------------\nPostgrex         | `analyze`, `verbose`, `costs`, `settings`, `buffers`, `timing`, `summary`, `format`, `plan`, `wrap_in_transaction`\nMyXQL            | `format`, `wrap_in_transaction`\n\nAll options except `format` are boolean valued and default to `false`.\n\nThe allowed `format` values are `:map`, `:yaml`, and `:text`:\n  * `:map` is the deserialized JSON encoding.\n  * `:yaml` and `:text` return the result as a string.\n\nThe built-in adapters support the following formats:\n  * Postgrex: `:map`, `:yaml` and `:text`\n  * MyXQL: `:map` and `:text`\n\nThe `wrap_in_transaction` option is a boolean that controls whether the command is run inside of a\ntransaction that is rolled back. This is useful when, for example, you'd like to use `analyze: true`\non an update or delete query without modifying data. Defaults to `true`.\n\nThe `:plan` option in Postgrex can take the values `:custom` or `:fallback_generic`. When `:custom`\nis specified, the explain plan generated will consider the specific values of the query parameters\nthat are supplied. When using `:fallback_generic`, the specific values of the query parameters will\nbe ignored. `:fallback_generic` does not use PostgreSQL's built-in support for a generic explain\nplan (available as of PostgreSQL 16), but instead uses a special implementation that works for PostgreSQL\nversions 12 and above. Defaults to `:custom`.\n\nAny other value passed to `opts` will be forwarded to the underlying adapter query function, including\nshared Repo options such as `:timeout`. Non built-in adapters may have specific behaviour and you should\nconsult their documentation for more details.\n\nFor version compatibility, please check your database's documentation:\n\n  * _Postgrex_: [PostgreSQL doc](https://www.postgresql.org/docs/current/sql-explain.html).\n  * _MyXQL_: [MySQL doc](https://dev.mysql.com/doc/refman/8.0/en/explain.html).","ref":"Soundboard.Repo.html#explain/3-options"},{"type":"function","title":"Soundboard.Repo.get/3","doc":"Callback implementation for  Ecto.Repo.get/3 .","ref":"Soundboard.Repo.html#get/3"},{"type":"function","title":"Soundboard.Repo.get!/3","doc":"Callback implementation for  Ecto.Repo.get!/3 .","ref":"Soundboard.Repo.html#get!/3"},{"type":"function","title":"Soundboard.Repo.get_by/3","doc":"Callback implementation for  Ecto.Repo.get_by/3 .","ref":"Soundboard.Repo.html#get_by/3"},{"type":"function","title":"Soundboard.Repo.get_by!/3","doc":"Callback implementation for  Ecto.Repo.get_by!/3 .","ref":"Soundboard.Repo.html#get_by!/3"},{"type":"function","title":"Soundboard.Repo.get_dynamic_repo/0","doc":"Callback implementation for  Ecto.Repo.get_dynamic_repo/0 .","ref":"Soundboard.Repo.html#get_dynamic_repo/0"},{"type":"function","title":"Soundboard.Repo.in_transaction?/0","doc":"Callback implementation for  Ecto.Repo.in_transaction?/0 .","ref":"Soundboard.Repo.html#in_transaction?/0"},{"type":"function","title":"Soundboard.Repo.insert/2","doc":"Callback implementation for  Ecto.Repo.insert/2 .","ref":"Soundboard.Repo.html#insert/2"},{"type":"function","title":"Soundboard.Repo.insert!/2","doc":"Callback implementation for  Ecto.Repo.insert!/2 .","ref":"Soundboard.Repo.html#insert!/2"},{"type":"function","title":"Soundboard.Repo.insert_all/3","doc":"Callback implementation for  Ecto.Repo.insert_all/3 .","ref":"Soundboard.Repo.html#insert_all/3"},{"type":"function","title":"Soundboard.Repo.insert_or_update/2","doc":"Callback implementation for  Ecto.Repo.insert_or_update/2 .","ref":"Soundboard.Repo.html#insert_or_update/2"},{"type":"function","title":"Soundboard.Repo.insert_or_update!/2","doc":"Callback implementation for  Ecto.Repo.insert_or_update!/2 .","ref":"Soundboard.Repo.html#insert_or_update!/2"},{"type":"function","title":"Soundboard.Repo.load/2","doc":"Callback implementation for  Ecto.Repo.load/2 .","ref":"Soundboard.Repo.html#load/2"},{"type":"function","title":"Soundboard.Repo.one/2","doc":"Callback implementation for  Ecto.Repo.one/2 .","ref":"Soundboard.Repo.html#one/2"},{"type":"function","title":"Soundboard.Repo.one!/2","doc":"Callback implementation for  Ecto.Repo.one!/2 .","ref":"Soundboard.Repo.html#one!/2"},{"type":"function","title":"Soundboard.Repo.preload/3","doc":"Callback implementation for  Ecto.Repo.preload/3 .","ref":"Soundboard.Repo.html#preload/3"},{"type":"function","title":"Soundboard.Repo.prepare_query/3","doc":"Callback implementation for  Ecto.Repo.prepare_query/3 .","ref":"Soundboard.Repo.html#prepare_query/3"},{"type":"function","title":"Soundboard.Repo.prepare_transaction/2","doc":"Callback implementation for  Ecto.Repo.prepare_transaction/2 .","ref":"Soundboard.Repo.html#prepare_transaction/2"},{"type":"function","title":"Soundboard.Repo.put_dynamic_repo/1","doc":"Callback implementation for  Ecto.Repo.put_dynamic_repo/1 .","ref":"Soundboard.Repo.html#put_dynamic_repo/1"},{"type":"function","title":"Soundboard.Repo.query/3","doc":"Runs a custom SQL query.\n\nIf the query was successful, it will return an `:ok` tuple containing\na map with at least two keys:\n\n  * `:num_rows` - the number of rows affected\n  * `:rows` - the result set as a list. `nil` may be returned\n    instead of the list if the command does not yield any row\n    as result (but still yields the number of affected rows,\n    like a `delete` command without returning would)","ref":"Soundboard.Repo.html#query/3"},{"type":"function","title":"Options - Soundboard.Repo.query/3","doc":"* `:log` - When false, does not log the query\n  * `:timeout` - Execute request timeout, accepts: `:infinity` (default: `15000`);","ref":"Soundboard.Repo.html#query/3-options"},{"type":"function","title":"Examples - Soundboard.Repo.query/3","doc":"iex> MyRepo.query(\"SELECT $1::integer + $2\", [40, 2])\n    {:ok, %{rows: [[42]], num_rows: 1}}\n\n    iex> Ecto.Adapters.SQL.query(MyRepo, \"SELECT $1::integer + $2\", [40, 2])\n    {:ok, %{rows: [[42]], num_rows: 1}}","ref":"Soundboard.Repo.html#query/3-examples"},{"type":"function","title":"Soundboard.Repo.query!/3","doc":"Same as `query/3` but returns result directly without `:ok` tuple\nand raises on invalid queries","ref":"Soundboard.Repo.html#query!/3"},{"type":"function","title":"Soundboard.Repo.query_many/3","doc":"Runs a custom SQL query that returns multiple results on the given repo.\n\nIn case of success, it must return an `:ok` tuple containing a list of\nmaps with at least two keys:\n\n  * `:num_rows` - the number of rows affected\n\n  * `:rows` - the result set as a list. `nil` may be returned\n    instead of the list if the command does not yield any row\n    as result (but still yields the number of affected rows,\n    like a `delete` command without returning would)","ref":"Soundboard.Repo.html#query_many/3"},{"type":"function","title":"Options - Soundboard.Repo.query_many/3","doc":"* `:log` - When false, does not log the query\n  * `:timeout` - Execute request timeout, accepts: `:infinity` (default: `15000`);","ref":"Soundboard.Repo.html#query_many/3-options"},{"type":"function","title":"Examples - Soundboard.Repo.query_many/3","doc":"iex> MyRepo.query_many(\"SELECT $1; SELECT $2;\", [40, 2])\n    {:ok, [%{rows: [[40]], num_rows: 1}, %{rows: [[2]], num_rows: 1}]}\n\n    iex> Ecto.Adapters.SQL.query_many(MyRepo, \"SELECT $1; SELECT $2;\", [40, 2])\n    {:ok, [%{rows: [[40]], num_rows: 1}, %{rows: [[2]], num_rows: 1}]}","ref":"Soundboard.Repo.html#query_many/3-examples"},{"type":"function","title":"Soundboard.Repo.query_many!/3","doc":"Same as `query_many/4` but returns result directly without `:ok` tuple\nand raises on invalid queries","ref":"Soundboard.Repo.html#query_many!/3"},{"type":"function","title":"Soundboard.Repo.reload/2","doc":"Callback implementation for  Ecto.Repo.reload/2 .","ref":"Soundboard.Repo.html#reload/2"},{"type":"function","title":"Soundboard.Repo.reload!/2","doc":"Callback implementation for  Ecto.Repo.reload!/2 .","ref":"Soundboard.Repo.html#reload!/2"},{"type":"function","title":"Soundboard.Repo.rollback/1","doc":"Callback implementation for  Ecto.Repo.rollback/1 .","ref":"Soundboard.Repo.html#rollback/1"},{"type":"function","title":"Soundboard.Repo.start_link/1","doc":"Callback implementation for  Ecto.Repo.start_link/1 .","ref":"Soundboard.Repo.html#start_link/1"},{"type":"function","title":"Soundboard.Repo.stop/1","doc":"Callback implementation for  Ecto.Repo.stop/1 .","ref":"Soundboard.Repo.html#stop/1"},{"type":"function","title":"Soundboard.Repo.stream/2","doc":"Callback implementation for  Ecto.Repo.stream/2 .","ref":"Soundboard.Repo.html#stream/2"},{"type":"function","title":"Soundboard.Repo.to_sql/3","doc":"Converts the given query to SQL according to its kind and the\nadapter in the given repository.","ref":"Soundboard.Repo.html#to_sql/3"},{"type":"function","title":"Examples - Soundboard.Repo.to_sql/3","doc":"The examples below are meant for reference. Each adapter will\nreturn a different result:\n\n    iex> MyRepo.to_sql(:all, Post)\n    {\"SELECT p.id, p.title, p.inserted_at, p.created_at FROM posts as p\", []}\n\n    iex> MyRepo.to_sql(:update_all, from(p in Post, update: [set: [title: ^\"hello\"]]))\n    {\"UPDATE posts AS p SET title = $1\", [\"hello\"]}\n\n    iex> Ecto.Adapters.SQL.to_sql(:all, MyRepo, Post)\n    {\"SELECT p.id, p.title, p.inserted_at, p.created_at FROM posts as p\", []}","ref":"Soundboard.Repo.html#to_sql/3-examples"},{"type":"function","title":"Soundboard.Repo.transact/2","doc":"Callback implementation for  Ecto.Repo.transact/2 .","ref":"Soundboard.Repo.html#transact/2"},{"type":"function","title":"Soundboard.Repo.transaction/2","doc":"Callback implementation for  Ecto.Repo.transaction/2 .","ref":"Soundboard.Repo.html#transaction/2"},{"type":"function","title":"Soundboard.Repo.update/2","doc":"Callback implementation for  Ecto.Repo.update/2 .","ref":"Soundboard.Repo.html#update/2"},{"type":"function","title":"Soundboard.Repo.update!/2","doc":"Callback implementation for  Ecto.Repo.update!/2 .","ref":"Soundboard.Repo.html#update!/2"},{"type":"function","title":"Soundboard.Repo.update_all/3","doc":"Callback implementation for  Ecto.Repo.update_all/3 .","ref":"Soundboard.Repo.html#update_all/3"},{"type":"module","title":"Soundboard.Sound","doc":"Sound schema.","ref":"Soundboard.Sound.html"},{"type":"type","title":"Soundboard.Sound.t/0","doc":"","ref":"Soundboard.Sound.html#t:t/0"},{"type":"function","title":"Soundboard.Sound.changeset/2","doc":"","ref":"Soundboard.Sound.html#changeset/2"},{"type":"function","title":"Soundboard.Sound.with_tags/1","doc":"","ref":"Soundboard.Sound.html#with_tags/1"},{"type":"module","title":"Soundboard.SoundTag","doc":"The SoundTag module.","ref":"Soundboard.SoundTag.html"},{"type":"function","title":"Soundboard.SoundTag.changeset/2","doc":"","ref":"Soundboard.SoundTag.html#changeset/2"},{"type":"module","title":"Soundboard.Sounds","doc":"Sound domain context.","ref":"Soundboard.Sounds.html"},{"type":"function","title":"Soundboard.Sounds.create_error_message/1","doc":"","ref":"Soundboard.Sounds.html#create_error_message/1"},{"type":"function","title":"Soundboard.Sounds.create_sound/1","doc":"","ref":"Soundboard.Sounds.html#create_sound/1"},{"type":"function","title":"Soundboard.Sounds.delete_sound/2","doc":"","ref":"Soundboard.Sounds.html#delete_sound/2"},{"type":"function","title":"Soundboard.Sounds.fetch_sound/2","doc":"","ref":"Soundboard.Sounds.html#fetch_sound/2"},{"type":"function","title":"Soundboard.Sounds.fetch_sound_id/2","doc":"","ref":"Soundboard.Sounds.html#fetch_sound_id/2"},{"type":"function","title":"Soundboard.Sounds.filename_taken_excluding?/3","doc":"","ref":"Soundboard.Sounds.html#filename_taken_excluding?/3"},{"type":"function","title":"Soundboard.Sounds.get_recent_uploads/1","doc":"","ref":"Soundboard.Sounds.html#get_recent_uploads/1"},{"type":"function","title":"Soundboard.Sounds.get_user_join_sound_by_discord_id/2","doc":"","ref":"Soundboard.Sounds.html#get_user_join_sound_by_discord_id/2"},{"type":"function","title":"Soundboard.Sounds.get_user_leave_sound_by_discord_id/2","doc":"","ref":"Soundboard.Sounds.html#get_user_leave_sound_by_discord_id/2"},{"type":"function","title":"Soundboard.Sounds.ids_by_filename/2","doc":"","ref":"Soundboard.Sounds.html#ids_by_filename/2"},{"type":"function","title":"Soundboard.Sounds.list_detailed/1","doc":"","ref":"Soundboard.Sounds.html#list_detailed/1"},{"type":"function","title":"Soundboard.Sounds.new_create_request/2","doc":"","ref":"Soundboard.Sounds.html#new_create_request/2"},{"type":"function","title":"Soundboard.Sounds.put_request_upload/2","doc":"","ref":"Soundboard.Sounds.html#put_request_upload/2"},{"type":"function","title":"Soundboard.Sounds.update_sound/3","doc":"","ref":"Soundboard.Sounds.html#update_sound/3"},{"type":"function","title":"Soundboard.Sounds.validate_create/1","doc":"","ref":"Soundboard.Sounds.html#validate_create/1"},{"type":"module","title":"Soundboard.Sounds.Management","doc":"Domain-level sound update/delete operations used by LiveViews.\n\nSound metadata edits are collaborative for signed-in users, while deletion\nremains restricted to the original uploader. Per-user join/leave preferences\nare stored separately so editors keep their own settings without taking over\nsound ownership.","ref":"Soundboard.Sounds.Management.html"},{"type":"function","title":"Soundboard.Sounds.Management.delete_sound/2","doc":"","ref":"Soundboard.Sounds.Management.html#delete_sound/2"},{"type":"function","title":"Soundboard.Sounds.Management.update_sound/3","doc":"","ref":"Soundboard.Sounds.Management.html#update_sound/3"},{"type":"module","title":"Soundboard.Sounds.Tags","doc":"Domain helpers for searching, resolving, and persisting sound tags.","ref":"Soundboard.Sounds.Tags.html"},{"type":"function","title":"Soundboard.Sounds.Tags.all_for_sounds/1","doc":"","ref":"Soundboard.Sounds.Tags.html#all_for_sounds/1"},{"type":"function","title":"Soundboard.Sounds.Tags.count_sounds_with_tag/2","doc":"","ref":"Soundboard.Sounds.Tags.html#count_sounds_with_tag/2"},{"type":"function","title":"Soundboard.Sounds.Tags.find_or_create/1","doc":"","ref":"Soundboard.Sounds.Tags.html#find_or_create/1"},{"type":"function","title":"Soundboard.Sounds.Tags.resolve/1","doc":"","ref":"Soundboard.Sounds.Tags.html#resolve/1"},{"type":"function","title":"Soundboard.Sounds.Tags.resolve_many/1","doc":"","ref":"Soundboard.Sounds.Tags.html#resolve_many/1"},{"type":"function","title":"Soundboard.Sounds.Tags.search/1","doc":"","ref":"Soundboard.Sounds.Tags.html#search/1"},{"type":"function","title":"Soundboard.Sounds.Tags.tag_selected?/2","doc":"","ref":"Soundboard.Sounds.Tags.html#tag_selected?/2"},{"type":"function","title":"Soundboard.Sounds.Tags.update_sound_tags/2","doc":"","ref":"Soundboard.Sounds.Tags.html#update_sound_tags/2"},{"type":"module","title":"Soundboard.Sounds.Uploads","doc":"Canonical sound upload/create API.","ref":"Soundboard.Sounds.Uploads.html"},{"type":"type","title":"Soundboard.Sounds.Uploads.create_error/0","doc":"","ref":"Soundboard.Sounds.Uploads.html#t:create_error/0"},{"type":"type","title":"Soundboard.Sounds.Uploads.create_result/0","doc":"","ref":"Soundboard.Sounds.Uploads.html#t:create_result/0"},{"type":"function","title":"Soundboard.Sounds.Uploads.create/1","doc":"","ref":"Soundboard.Sounds.Uploads.html#create/1"},{"type":"function","title":"Soundboard.Sounds.Uploads.error_message/1","doc":"","ref":"Soundboard.Sounds.Uploads.html#error_message/1"},{"type":"function","title":"Soundboard.Sounds.Uploads.validate/1","doc":"","ref":"Soundboard.Sounds.Uploads.html#validate/1"},{"type":"module","title":"Soundboard.Sounds.Uploads.CreateRequest","doc":"The input to create a sound, built from request params (`new/2`).\n\nA local file only comes in as a `%Plug.Upload{}`, the file Plug received\nin the request; any other `file`/`upload` param (such as a map naming a\nserver path) is ignored, so a client can never make the server copy one of\nits own files. Callers that already hold a received file (the LiveView's\nconsumed upload entry) attach it with `put_upload/2`.","ref":"Soundboard.Sounds.Uploads.CreateRequest.html"},{"type":"type","title":"Soundboard.Sounds.Uploads.CreateRequest.t/0","doc":"","ref":"Soundboard.Sounds.Uploads.CreateRequest.html#t:t/0"},{"type":"type","title":"Soundboard.Sounds.Uploads.CreateRequest.upload/0","doc":"","ref":"Soundboard.Sounds.Uploads.CreateRequest.html#t:upload/0"},{"type":"function","title":"Soundboard.Sounds.Uploads.CreateRequest.new/2","doc":"","ref":"Soundboard.Sounds.Uploads.CreateRequest.html#new/2"},{"type":"function","title":"Soundboard.Sounds.Uploads.CreateRequest.put_upload/2","doc":"","ref":"Soundboard.Sounds.Uploads.CreateRequest.html#put_upload/2"},{"type":"module","title":"Soundboard.Stats","doc":"Handles the stats of the soundboard.","ref":"Soundboard.Stats.html"},{"type":"type","title":"Soundboard.Stats.leaderboard_entry/0","doc":"","ref":"Soundboard.Stats.html#t:leaderboard_entry/0"},{"type":"type","title":"Soundboard.Stats.recent_play_entry/0","doc":"","ref":"Soundboard.Stats.html#t:recent_play_entry/0"},{"type":"function","title":"Soundboard.Stats.broadcast_stats_update/0","doc":"","ref":"Soundboard.Stats.html#broadcast_stats_update/0"},{"type":"function","title":"Soundboard.Stats.get_recent_plays/1","doc":"","ref":"Soundboard.Stats.html#get_recent_plays/1"},{"type":"function","title":"Soundboard.Stats.get_top_sounds/3","doc":"","ref":"Soundboard.Stats.html#get_top_sounds/3"},{"type":"function","title":"Soundboard.Stats.get_top_users/3","doc":"","ref":"Soundboard.Stats.html#get_top_users/3"},{"type":"function","title":"Soundboard.Stats.track_play/3","doc":"","ref":"Soundboard.Stats.html#track_play/3"},{"type":"module","title":"Soundboard.Stats.Play","doc":"The Play module.","ref":"Soundboard.Stats.Play.html"},{"type":"type","title":"Soundboard.Stats.Play.t/0","doc":"","ref":"Soundboard.Stats.Play.html#t:t/0"},{"type":"function","title":"Soundboard.Stats.Play.changeset/2","doc":"","ref":"Soundboard.Stats.Play.html#changeset/2"},{"type":"module","title":"Soundboard.TableOwner","doc":"Owns the app's shared ETS tables (billing's processed events, Stripe\ncustomers and subscriptions, and the sound metadata cache).\n\nAn ETS table dies with the process that created it. Webhooks and billing\npages run in short-lived request processes, and audio players stop when\nidle, so tables are created by this supervised process instead and live as\nlong as the application.","ref":"Soundboard.TableOwner.html"},{"type":"function","title":"Soundboard.TableOwner.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"Soundboard.TableOwner.html#child_spec/1"},{"type":"function","title":"Soundboard.TableOwner.ensure_tables/1","doc":"Makes sure every table in `tables` exists, owned by this process.","ref":"Soundboard.TableOwner.html#ensure_tables/1"},{"type":"function","title":"Soundboard.TableOwner.start_link/1","doc":"","ref":"Soundboard.TableOwner.html#start_link/1"},{"type":"module","title":"Soundboard.Tag","doc":"The Tag module.","ref":"Soundboard.Tag.html"},{"type":"function","title":"Soundboard.Tag.changeset/2","doc":"","ref":"Soundboard.Tag.html#changeset/2"},{"type":"function","title":"Soundboard.Tag.search/2","doc":"","ref":"Soundboard.Tag.html#search/2"},{"type":"module","title":"Soundboard.Tenants","doc":"Multi-tenant context.\n\nA tenant is a Discord guild with a provisioned soundboard: a row in the\n`guilds` table plus a slug that maps to `{slug}.soundbored.app`.\n\nBackward compatibility: every guild-scoped operation falls back to\n`default_guild_id/0` when no guild is given, so existing single-guild\ndeployments behave identically with zero configuration.","ref":"Soundboard.Tenants.html"},{"type":"function","title":"Soundboard.Tenants.bot_guilds/0","doc":"Lists the guilds the shared Discord bot is a member of, with their tenant\nrows (if claimed). Used by the guild switcher and onboarding.","ref":"Soundboard.Tenants.html#bot_guilds/0"},{"type":"function","title":"Soundboard.Tenants.claim_slug/2","doc":"Claims `{slug}` for the given Discord guild, creating the tenant row if\nneeded. Returns `{:error, :slug_taken}` / `{:error, :invalid_slug}` /\n`{:error, changeset}`.","ref":"Soundboard.Tenants.html#claim_slug/2"},{"type":"function","title":"Soundboard.Tenants.default_guild_id/0","doc":"The guild used when no tenant is specified.\n\nResolution order: `SOUNDBOARD_DEFAULT_GUILD_ID` env (configured as\n`:default_guild_id`), the existing `DISCORD_REQUIRED_GUILD_ID` env\n(configured as `:required_guild_id`), the bot's sole guild (discovered via\n`GuildCache` for zero-config single-guild deployments that never set the\nlegacy envs), then the literal `\"default\"`.\n\nThe sole-guild step keeps deployments from before multi-tenancy\nzero-config on upgrade: the migration backfills `\"default\"`, and\n`reconcile_default_guild/0` repoints those rows once the guild cache is\npopulated. A bot in several guilds has no sole guild: those hosts configure\na guild or claim a slug.","ref":"Soundboard.Tenants.html#default_guild_id/0"},{"type":"function","title":"Soundboard.Tenants.get_by_slug/1","doc":"","ref":"Soundboard.Tenants.html#get_by_slug/1"},{"type":"function","title":"Soundboard.Tenants.get_guild/1","doc":"","ref":"Soundboard.Tenants.html#get_guild/1"},{"type":"function","title":"Soundboard.Tenants.get_or_create_guild/2","doc":"The guild's tenant row, created when missing with the provisional slug\n`guild- ` (unique by construction) until someone claims a subdomain\n(`claim_slug/2`).","ref":"Soundboard.Tenants.html#get_or_create_guild/2"},{"type":"function","title":"Soundboard.Tenants.list_guilds/0","doc":"","ref":"Soundboard.Tenants.html#list_guilds/0"},{"type":"function","title":"Soundboard.Tenants.put_default_guild_id/1","doc":"Changeset helper: defaults a blank `guild_id` to the default guild, so\npre-tenant call sites and single-guild deployments keep working unchanged.","ref":"Soundboard.Tenants.html#put_default_guild_id/1"},{"type":"function","title":"Soundboard.Tenants.reconcile_default_guild/0","doc":"One-time self-heal for deployments upgrading from pre-multi-tenant code that\nnever configured a guild env (see `default_guild_id/0`).\n\nWhen no env is configured and the bot is in exactly one guild, that guild is\nthe deployment's guild. The migration backfills the literal `\"default\"`;\nthis repoints those rows to the real guild id so web queries and voice\nplaybacks line up after upgrading.\n\nGuarded: no-ops when a guild env is configured (those deployments backfill\ncorrectly at migration time) or when the bot is in zero/many guilds (then an\nexplicit identity — env or slug claim — is required). Idempotent.","ref":"Soundboard.Tenants.html#reconcile_default_guild/0"},{"type":"function","title":"Soundboard.Tenants.reserved_slugs/0","doc":"","ref":"Soundboard.Tenants.html#reserved_slugs/0"},{"type":"function","title":"Soundboard.Tenants.scope_guild_id/1","doc":"The guild id to scope by: the given id, or the default guild.","ref":"Soundboard.Tenants.html#scope_guild_id/1"},{"type":"function","title":"Soundboard.Tenants.slug_available?/1","doc":"Whether a slug can be claimed (valid format, not reserved, not taken).","ref":"Soundboard.Tenants.html#slug_available?/1"},{"type":"function","title":"Soundboard.Tenants.storage_cap/1","doc":"The storage cap for a guild: its own `max_storage_bytes`, or nil when the\nguild has no cap, which means unlimited. Caps exist only where\nsubscriptions put them: on hosted, the billing webhook writes exact plan\ncaps and 0 once the subscription ends (no plan: nothing can be added);\nself-hosted installs have no cap at all.","ref":"Soundboard.Tenants.html#storage_cap/1"},{"type":"function","title":"Soundboard.Tenants.storage_used/1","doc":"Bytes of uploaded storage used by a guild. Sounds with unknown size\n(`byte_size = 0`, e.g. rows created before guild scoping) count as zero, so\nexisting deployments are never retroactively blocked by a cap.","ref":"Soundboard.Tenants.html#storage_used/1"},{"type":"function","title":"Soundboard.Tenants.within_storage_limit?/2","doc":"Whether adding a sound of `incoming_bytes` stays within the guild's cap.\nAn uncapped guild (self-hosted) is always within its limit; a guild with\nno plan (cap 0) cannot add anything, not even a URL sound.","ref":"Soundboard.Tenants.html#within_storage_limit?/2"},{"type":"module","title":"Soundboard.Tenants.Guild","doc":"A tenant: one Discord guild's provisioned soundboard.","ref":"Soundboard.Tenants.Guild.html"},{"type":"type","title":"Soundboard.Tenants.Guild.t/0","doc":"","ref":"Soundboard.Tenants.Guild.html#t:t/0"},{"type":"module","title":"Soundboard.Tenants.Membership","doc":"Who may use and who may manage a guild's soundboard.\n\nA user may use a guild's soundboard only while they are a member of that\nDiscord guild. The deployment's default guild (`Tenants.default_guild_id/0`)\nis open to every signed-in user, so self-hosted installs keep working with\nno configuration (the role check already gates who signs in there).\n\nMembership is read from Discord through `EDA.Cache.fetch_member/2`: the\ngateway's member cache first, the REST API on a miss. When Discord cannot\nbe reached the answer is no.","ref":"Soundboard.Tenants.Membership.html"},{"type":"function","title":"Soundboard.Tenants.Membership.member?/2","doc":"","ref":"Soundboard.Tenants.Membership.html#member?/2"},{"type":"function","title":"Soundboard.Tenants.Membership.owner?/2","doc":"Whether the user may manage the guild (claim its slug, run its billing):\nonly the owner recorded when it was provisioned. A guild with no recorded\nowner is manageable only when it is the default guild.","ref":"Soundboard.Tenants.Membership.html#owner?/2"},{"type":"module","title":"Soundboard.UploadsPath","doc":"Central source of truth for uploaded sound storage paths.","ref":"Soundboard.UploadsPath.html"},{"type":"type","title":"Soundboard.UploadsPath.path_input/0","doc":"","ref":"Soundboard.UploadsPath.html#t:path_input/0"},{"type":"function","title":"Soundboard.UploadsPath.dir/0","doc":"","ref":"Soundboard.UploadsPath.html#dir/0"},{"type":"function","title":"Soundboard.UploadsPath.file_path/1","doc":"","ref":"Soundboard.UploadsPath.html#file_path/1"},{"type":"function","title":"Soundboard.UploadsPath.safe_joined_path/1","doc":"","ref":"Soundboard.UploadsPath.html#safe_joined_path/1"},{"type":"module","title":"Soundboard.UserSoundSetting","doc":"The UserSoundSetting module.","ref":"Soundboard.UserSoundSetting.html"},{"type":"function","title":"Soundboard.UserSoundSetting.changeset/2","doc":"","ref":"Soundboard.UserSoundSetting.html#changeset/2"},{"type":"function","title":"Soundboard.UserSoundSetting.clear_conflicting_settings/5","doc":"","ref":"Soundboard.UserSoundSetting.html#clear_conflicting_settings/5"},{"type":"module","title":"Soundboard.Volume","doc":"Helpers for working with volume percentages and decimal ratios.","ref":"Soundboard.Volume.html"},{"type":"type","title":"Soundboard.Volume.percent/0","doc":"","ref":"Soundboard.Volume.html#t:percent/0"},{"type":"function","title":"Soundboard.Volume.clamp_percent/1","doc":"","ref":"Soundboard.Volume.html#clamp_percent/1"},{"type":"function","title":"Soundboard.Volume.decimal_to_percent/1","doc":"","ref":"Soundboard.Volume.html#decimal_to_percent/1"},{"type":"function","title":"Soundboard.Volume.normalize_percent/2","doc":"","ref":"Soundboard.Volume.html#normalize_percent/2"},{"type":"function","title":"Soundboard.Volume.percent_to_decimal/1","doc":"","ref":"Soundboard.Volume.html#percent_to_decimal/1"},{"type":"function","title":"Soundboard.Volume.percent_to_decimal/2","doc":"","ref":"Soundboard.Volume.html#percent_to_decimal/2"},{"type":"module","title":"SoundboardWeb","doc":"The entrypoint for defining your web interface, such\nas controllers, components, channels, and so on.\n\nThis can be used in your application as:\n\n    use SoundboardWeb, :controller\n    use SoundboardWeb, :html\n\nThe definitions below will be executed for every controller,\ncomponent, etc, so keep them short and clean, focused\non imports, uses and aliases.\n\nDo NOT define functions inside the quoted expressions\nbelow. Instead, define additional modules and import\nthose modules here.","ref":"SoundboardWeb.html"},{"type":"macro","title":"SoundboardWeb.__using__/1","doc":"When used, dispatch to the appropriate controller/live_view/etc.","ref":"SoundboardWeb.html#__using__/1"},{"type":"function","title":"SoundboardWeb.channel/0","doc":"","ref":"SoundboardWeb.html#channel/0"},{"type":"function","title":"SoundboardWeb.controller/0","doc":"","ref":"SoundboardWeb.html#controller/0"},{"type":"function","title":"SoundboardWeb.html/0","doc":"","ref":"SoundboardWeb.html#html/0"},{"type":"function","title":"SoundboardWeb.live_component/0","doc":"","ref":"SoundboardWeb.html#live_component/0"},{"type":"function","title":"SoundboardWeb.live_view/0","doc":"","ref":"SoundboardWeb.html#live_view/0"},{"type":"function","title":"SoundboardWeb.router/0","doc":"","ref":"SoundboardWeb.html#router/0"},{"type":"function","title":"SoundboardWeb.static_paths/0","doc":"","ref":"SoundboardWeb.html#static_paths/0"},{"type":"function","title":"SoundboardWeb.verified_routes/0","doc":"","ref":"SoundboardWeb.html#verified_routes/0"},{"type":"module","title":"SoundboardWeb.API.SoundController","doc":"The JSON API. `SoundboardWeb.Plugs.APIAuth` has already authenticated the\ntoken's user and `SoundboardWeb.Plugs.Tenant` resolved the guild, so every\naction acts as `:current_user` in `:current_guild_id`.","ref":"SoundboardWeb.API.SoundController.html"},{"type":"function","title":"SoundboardWeb.API.SoundController.create/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#create/2"},{"type":"function","title":"SoundboardWeb.API.SoundController.favorites/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#favorites/2"},{"type":"function","title":"SoundboardWeb.API.SoundController.file/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#file/2"},{"type":"function","title":"SoundboardWeb.API.SoundController.index/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#index/2"},{"type":"function","title":"SoundboardWeb.API.SoundController.play/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#play/2"},{"type":"function","title":"SoundboardWeb.API.SoundController.stop/2","doc":"","ref":"SoundboardWeb.API.SoundController.html#stop/2"},{"type":"module","title":"SoundboardWeb.AuthController","doc":"Discord sign-in. A signed-out visitor who opened `/g/:slug` has that slug\nkept in the session (`:pending_slug`), and lands on it after signing in.","ref":"SoundboardWeb.AuthController.html"},{"type":"function","title":"SoundboardWeb.AuthController.callback/2","doc":"","ref":"SoundboardWeb.AuthController.html#callback/2"},{"type":"function","title":"SoundboardWeb.AuthController.logout/2","doc":"","ref":"SoundboardWeb.AuthController.html#logout/2"},{"type":"function","title":"SoundboardWeb.AuthController.request/2","doc":"Only reached for providers Ueberauth does not handle: the Ueberauth plug\nanswers `/auth/discord` itself by redirecting to Discord.","ref":"SoundboardWeb.AuthController.html#request/2"},{"type":"function","title":"SoundboardWeb.AuthController.test_login/2","doc":"Test-only sign-in for Playwright e2e runs. The route is registered only when\n`:enable_test_login` is configured, which is dev/test — never prod.","ref":"SoundboardWeb.AuthController.html#test_login/2"},{"type":"module","title":"SoundboardWeb.BillingController","doc":"Stripe subscriptions: plan options, checkout, customer portal, and the\npublic webhook receiver (signature-verified, no session auth).\n\nOnly a guild's owner (`Soundboard.Tenants.Membership.owner?/2`) may open\nits portal, change or cancel its plan, or start a checkout for it once it\nhas an owner; a new guild can be subscribed by the member who picked it.\n\nThe webhook signature is computed over the raw request bytes, so the\nwebhook reads the untouched JSON body that `SoundboardWeb.RawBodyReader`\nkept in `:raw_body`, never re-encoded JSON.","ref":"SoundboardWeb.BillingController.html"},{"type":"function","title":"SoundboardWeb.BillingController.cancel/2","doc":"Cancels the session guild's subscription at period end.","ref":"SoundboardWeb.BillingController.html#cancel/2"},{"type":"function","title":"SoundboardWeb.BillingController.change/2","doc":"Switches the session guild's subscription to another price (tier or interval).","ref":"SoundboardWeb.BillingController.html#change/2"},{"type":"function","title":"SoundboardWeb.BillingController.checkout/2","doc":"Starts Stripe Checkout. The guild id comes from the session's pending\nbilling guild (set when a switch to an unpaid guild was gated) or the\npicked soundboard (a tenant row, not the default-guild fallback); with\nneither, the user is sent to pick one. `Billing` puts it into\n`client_reference_id` and metadata so the webhook can provision the right\ntenant.","ref":"SoundboardWeb.BillingController.html#checkout/2"},{"type":"function","title":"SoundboardWeb.BillingController.index/2","doc":"","ref":"SoundboardWeb.BillingController.html#index/2"},{"type":"function","title":"SoundboardWeb.BillingController.portal/2","doc":"Opens the Stripe customer portal for the session's guild.","ref":"SoundboardWeb.BillingController.html#portal/2"},{"type":"function","title":"SoundboardWeb.BillingController.webhook/2","doc":"Public Stripe webhook receiver. No session auth — the Stripe signature\nheader is the credential. Bad signatures and malformed payloads get a 400;\nduplicates get a 200 so Stripe stops retrying.","ref":"SoundboardWeb.BillingController.html#webhook/2"},{"type":"module","title":"SoundboardWeb.BillingHTML","doc":"Templates for the billing pages (plan options, storage usage, upgrade).","ref":"SoundboardWeb.BillingHTML.html"},{"type":"function","title":"SoundboardWeb.BillingHTML.billing/1","doc":"","ref":"SoundboardWeb.BillingHTML.html#billing/1"},{"type":"function","title":"SoundboardWeb.BillingHTML.cta_label/1","doc":"Checkout button label by relationship to the current plan.","ref":"SoundboardWeb.BillingHTML.html#cta_label/1"},{"type":"function","title":"SoundboardWeb.BillingHTML.current_tier_cap/1","doc":"Storage cap for a tier atom (:pro/:studio), used for upgrade/downgrade math.","ref":"SoundboardWeb.BillingHTML.html#current_tier_cap/1"},{"type":"function","title":"SoundboardWeb.BillingHTML.form_label/2","doc":"Label for change-plan (existing subscription) buttons, per billing interval.","ref":"SoundboardWeb.BillingHTML.html#form_label/2"},{"type":"module","title":"SoundboardWeb.Components.FlashComponent","doc":"The flash component.","ref":"SoundboardWeb.Components.FlashComponent.html"},{"type":"function","title":"SoundboardWeb.Components.FlashComponent.flash/1","doc":"","ref":"SoundboardWeb.Components.FlashComponent.html#flash/1"},{"type":"module","title":"SoundboardWeb.Components.Layouts.Navbar","doc":"The navbar component. A plain function component so it renders in both\nLiveViews and controller-rendered pages; the mobile menu toggles entirely\nclient-side via JS.","ref":"SoundboardWeb.Components.Layouts.Navbar.html"},{"type":"function","title":"SoundboardWeb.Components.Layouts.Navbar.mobile_nav_link/1","doc":"","ref":"SoundboardWeb.Components.Layouts.Navbar.html#mobile_nav_link/1"},{"type":"function","title":"SoundboardWeb.Components.Layouts.Navbar.nav_link/1","doc":"","ref":"SoundboardWeb.Components.Layouts.Navbar.html#nav_link/1"},{"type":"function","title":"SoundboardWeb.Components.Layouts.Navbar.navbar/1","doc":"","ref":"SoundboardWeb.Components.Layouts.Navbar.html#navbar/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Layouts.Navbar.navbar/1","doc":"* `current_user` (`:map`) - Defaults to `nil`.\n* `current_path` (`:string`) - Defaults to `nil`.\n* `presences` (`:map`) - Defaults to `%{}`.\n* `app_unlocked` (`:boolean`) - Defaults to `true`.","ref":"SoundboardWeb.Components.Layouts.Navbar.html#navbar/1-attributes"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.DeleteModal","doc":"The delete modal component.","ref":"SoundboardWeb.Components.Soundboard.DeleteModal.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.DeleteModal.delete_modal/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.DeleteModal.html#delete_modal/1"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.EditModal","doc":"The edit modal component.","ref":"SoundboardWeb.Components.Soundboard.EditModal.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.EditModal.edit_modal/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.EditModal.html#edit_modal/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.EditModal.edit_modal/1","doc":"* `flash` (`:map`) - Defaults to `%{}`.\n* `edit_name_error` (`:string`) - Defaults to `nil`.\n* `current_user` (`:map`) (required)\n* `current_sound` (`:map`) (required)\n* `tag_input` (`:string`) - Defaults to `\"\"`.\n* `tag_suggestions` (`:list`) - Defaults to `[]`.","ref":"SoundboardWeb.Components.Soundboard.EditModal.html#edit_modal/1-attributes"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.Helpers","doc":"Helper functions for the soundboard.","ref":"SoundboardWeb.Components.Soundboard.Helpers.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.Helpers.format_bytes/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.Helpers.html#format_bytes/1"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.TagComponents","doc":"Shared tag UI helpers for the soundboard modals.","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.TagComponents.tag_badge_list/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_badge_list/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.TagComponents.tag_badge_list/1","doc":"* `tags` (`:list`) - Defaults to `[]`.\n* `remove_event` (`:string`) (required)\n* `tag_key` (`:atom`) - Defaults to `:name`.\n* `wrapper_class` (`:string`) - Defaults to `\"mt-2 flex flex-wrap gap-2\"`.","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_badge_list/1-attributes"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.TagComponents.tag_filter_button/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_filter_button/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.TagComponents.tag_filter_button/1","doc":"* `tag` (`:any`) (required)\n* `selected_tags` (`:list`) (required)\n* `uploaded_files` (`:list`) (required)\n* `tag_key` (`:atom`) - Defaults to `:name`.\n* `click_event` (`:string`) - Defaults to `\"toggle_tag_filter\"`.\n* `class` (`:any`) - Defaults to `[]`.","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_filter_button/1-attributes"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.TagComponents.tag_input_field/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_input_field/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.TagComponents.tag_input_field/1","doc":"* `value` (`:string`) - Defaults to `\"\"`.\n* `placeholder` (`:string`) - Defaults to `\"Type a tag and press Enter...\"`.\n* `input_id` (`:string`) - Defaults to `nil`.\n* `disabled` (`:boolean`) - Defaults to `false`.\n* `class` (`:string`) - Defaults to `\"\"`.\n* `onkeydown` (`:string`) - Defaults to `nil`.\n* `autocomplete` (`:string`) - Defaults to `nil`.\n* Global attributes are accepted.","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_input_field/1-attributes"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.TagComponents.tag_suggestions_dropdown/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_suggestions_dropdown/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.TagComponents.tag_suggestions_dropdown/1","doc":"* `tag_input` (`:string`) - Defaults to `\"\"`.\n* `tag_suggestions` (`:list`) - Defaults to `[]`.\n* `select_event` (`:string`) (required)\n* `tag_key` (`:atom`) - Defaults to `:name`.\n* `wrapper_class` (`:string`) - Defaults to `\"absolute z-10 mt-1 w-full bg-white dark:bg-gray-700 shadow-lg max-h-60 rounded-md py-1 text-base overflow-auto focus:outline-none sm:text-sm\"`.\n* `suggestion_class` (`:string`) - Defaults to `\"w-full text-left px-4 py-2 text-sm hover:bg-blue-50 dark:hover:bg-blue-900 dark:text-gray-100\"`.","ref":"SoundboardWeb.Components.Soundboard.TagComponents.html#tag_suggestions_dropdown/1-attributes"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.UploadModal","doc":"The upload modal component.","ref":"SoundboardWeb.Components.Soundboard.UploadModal.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.UploadModal.upload_modal/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.UploadModal.html#upload_modal/1"},{"type":"module","title":"SoundboardWeb.Components.Soundboard.VolumeControl","doc":"Shared volume slider with preview support for upload/edit modals.","ref":"SoundboardWeb.Components.Soundboard.VolumeControl.html"},{"type":"function","title":"SoundboardWeb.Components.Soundboard.VolumeControl.volume_control/1","doc":"","ref":"SoundboardWeb.Components.Soundboard.VolumeControl.html#volume_control/1"},{"type":"function","title":"Attributes - SoundboardWeb.Components.Soundboard.VolumeControl.volume_control/1","doc":"* `id` (`:string`) - Defaults to `nil`.\n* `value` (`:integer`) (required)\n* `target` (`:string`) (required)\n* `push_event` (`:string`) - Defaults to `\"update_volume\"`.\n* `label` (`:string`) - Defaults to `\"Volume\"`.\n* `input_name` (`:string`) - Defaults to `\"volume\"`.\n* `preview_disabled` (`:boolean`) - Defaults to `false`.\n* `preview_label` (`:string`) - Defaults to `\"Preview\"`.\n* `max_percent` (`:integer`) - Defaults to `150`.\n* Global attributes are accepted.","ref":"SoundboardWeb.Components.Soundboard.VolumeControl.html#volume_control/1-attributes"},{"type":"module","title":"SoundboardWeb.CoreComponents","doc":"The flash notices and icons every page uses, and the JS commands that show\nand hide them. Icons are [heroicons](https://heroicons.com), bundled into\napp.css by the Tailwind plugin.","ref":"SoundboardWeb.CoreComponents.html"},{"type":"function","title":"SoundboardWeb.CoreComponents.flash/1","doc":"Renders a flash notice: the inner block if given, otherwise the flash\nmessage of the given kind.\n\n    <.flash kind={:info} flash={@flash} />\n    <.flash kind={:info} phx-mounted={show(\"#flash\")}>Welcome Back!</.flash>","ref":"SoundboardWeb.CoreComponents.html#flash/1"},{"type":"function","title":"Attributes - SoundboardWeb.CoreComponents.flash/1","doc":"* `id` (`:string`) - the container's id; `flash- ` when not given. Defaults to `nil`.\n* `flash` (`:map`) - the map of flash messages to display. Defaults to `%{}`.\n* `title` (`:string`) - Defaults to `nil`.\n* `kind` (`:atom`) - used for styling and flash lookup. Must be one of `:info`, or `:error`.\n* Global attributes are accepted. the arbitrary HTML attributes to add to the flash container.","ref":"SoundboardWeb.CoreComponents.html#flash/1-attributes"},{"type":"function","title":"Slots - SoundboardWeb.CoreComponents.flash/1","doc":"* `inner_block` - the optional inner block that renders the flash message.","ref":"SoundboardWeb.CoreComponents.html#flash/1-slots"},{"type":"function","title":"SoundboardWeb.CoreComponents.flash_group/1","doc":"The info and error flashes, and the notices shown while the connection is\nlost.\n\n    <.flash_group flash={@flash} />","ref":"SoundboardWeb.CoreComponents.html#flash_group/1"},{"type":"function","title":"Attributes - SoundboardWeb.CoreComponents.flash_group/1","doc":"* `flash` (`:map`) (required) - the map of flash messages.\n* `id` (`:string`) - the optional id of flash container. Defaults to `\"flash-group\"`.","ref":"SoundboardWeb.CoreComponents.html#flash_group/1-attributes"},{"type":"function","title":"SoundboardWeb.CoreComponents.hide/2","doc":"","ref":"SoundboardWeb.CoreComponents.html#hide/2"},{"type":"function","title":"SoundboardWeb.CoreComponents.icon/1","doc":"Renders a heroicon by its class name, sized and coloured with classes.\n\n    <.icon name=\"hero-x-mark-solid\" />\n    <.icon name=\"hero-arrow-path\" class=\"ml-1 w-3 h-3 animate-spin\" />","ref":"SoundboardWeb.CoreComponents.html#icon/1"},{"type":"function","title":"Attributes - SoundboardWeb.CoreComponents.icon/1","doc":"* `name` (`:string`) (required)\n* `class` (`:string`) - Defaults to `nil`.","ref":"SoundboardWeb.CoreComponents.html#icon/1-attributes"},{"type":"function","title":"SoundboardWeb.CoreComponents.show/2","doc":"","ref":"SoundboardWeb.CoreComponents.html#show/2"},{"type":"module","title":"SoundboardWeb.Endpoint","doc":"","ref":"SoundboardWeb.Endpoint.html"},{"type":"function","title":"SoundboardWeb.Endpoint.broadcast/3","doc":"Callback implementation for  Phoenix.Endpoint.broadcast/3 .","ref":"SoundboardWeb.Endpoint.html#broadcast/3"},{"type":"function","title":"SoundboardWeb.Endpoint.broadcast!/3","doc":"Callback implementation for  Phoenix.Endpoint.broadcast!/3 .","ref":"SoundboardWeb.Endpoint.html#broadcast!/3"},{"type":"function","title":"SoundboardWeb.Endpoint.broadcast_from/4","doc":"Callback implementation for  Phoenix.Endpoint.broadcast_from/4 .","ref":"SoundboardWeb.Endpoint.html#broadcast_from/4"},{"type":"function","title":"SoundboardWeb.Endpoint.broadcast_from!/4","doc":"Callback implementation for  Phoenix.Endpoint.broadcast_from!/4 .","ref":"SoundboardWeb.Endpoint.html#broadcast_from!/4"},{"type":"function","title":"SoundboardWeb.Endpoint.call/2","doc":"Callback implementation for  Plug.call/2 .","ref":"SoundboardWeb.Endpoint.html#call/2"},{"type":"function","title":"SoundboardWeb.Endpoint.child_spec/1","doc":"Returns the child specification to start the endpoint\nunder a supervision tree.","ref":"SoundboardWeb.Endpoint.html#child_spec/1"},{"type":"function","title":"SoundboardWeb.Endpoint.config/2","doc":"Returns the endpoint configuration for `key`\n\nReturns `default` if the key does not exist.","ref":"SoundboardWeb.Endpoint.html#config/2"},{"type":"function","title":"SoundboardWeb.Endpoint.config_change/2","doc":"Reloads the configuration given the application environment changes.","ref":"SoundboardWeb.Endpoint.html#config_change/2"},{"type":"function","title":"SoundboardWeb.Endpoint.host/0","doc":"Returns the host for the given endpoint.","ref":"SoundboardWeb.Endpoint.html#host/0"},{"type":"function","title":"SoundboardWeb.Endpoint.init/1","doc":"Callback implementation for  Plug.init/1 .","ref":"SoundboardWeb.Endpoint.html#init/1"},{"type":"function","title":"SoundboardWeb.Endpoint.local_broadcast/3","doc":"Callback implementation for  Phoenix.Endpoint.local_broadcast/3 .","ref":"SoundboardWeb.Endpoint.html#local_broadcast/3"},{"type":"function","title":"SoundboardWeb.Endpoint.local_broadcast_from/4","doc":"Callback implementation for  Phoenix.Endpoint.local_broadcast_from/4 .","ref":"SoundboardWeb.Endpoint.html#local_broadcast_from/4"},{"type":"function","title":"SoundboardWeb.Endpoint.path/1","doc":"Generates the path information when routing to this endpoint.","ref":"SoundboardWeb.Endpoint.html#path/1"},{"type":"function","title":"SoundboardWeb.Endpoint.script_name/0","doc":"Generates the script name.","ref":"SoundboardWeb.Endpoint.html#script_name/0"},{"type":"function","title":"SoundboardWeb.Endpoint.server_info/1","doc":"Returns the address and port that the server is running on","ref":"SoundboardWeb.Endpoint.html#server_info/1"},{"type":"function","title":"SoundboardWeb.Endpoint.start_link/1","doc":"Starts the endpoint supervision tree.\n\nAll other options are merged into the endpoint configuration.","ref":"SoundboardWeb.Endpoint.html#start_link/1"},{"type":"function","title":"SoundboardWeb.Endpoint.static_integrity/1","doc":"Generates a base64-encoded cryptographic hash (sha512) to a static file\nin `priv/static`. Meant to be used for Subresource Integrity with CDNs.","ref":"SoundboardWeb.Endpoint.html#static_integrity/1"},{"type":"function","title":"SoundboardWeb.Endpoint.static_lookup/1","doc":"Returns a two item tuple with the first item being the `static_path`\nand the second item being the `static_integrity`.","ref":"SoundboardWeb.Endpoint.html#static_lookup/1"},{"type":"function","title":"SoundboardWeb.Endpoint.static_path/1","doc":"Generates a route to a static file in `priv/static`.","ref":"SoundboardWeb.Endpoint.html#static_path/1"},{"type":"function","title":"SoundboardWeb.Endpoint.static_url/0","doc":"Generates the static URL without any path information.\n\nIt uses the configuration under `:static_url` to generate\nsuch. It falls back to `:url` if `:static_url` is not set.","ref":"SoundboardWeb.Endpoint.html#static_url/0"},{"type":"function","title":"SoundboardWeb.Endpoint.struct_url/0","doc":"Generates the endpoint base URL but as a `URI` struct.\n\nIt uses the configuration under `:url` to generate such.\nUseful for manipulating the URL data and passing it to\nURL helpers.","ref":"SoundboardWeb.Endpoint.html#struct_url/0"},{"type":"function","title":"SoundboardWeb.Endpoint.subscribe/2","doc":"Callback implementation for  Phoenix.Endpoint.subscribe/2 .","ref":"SoundboardWeb.Endpoint.html#subscribe/2"},{"type":"function","title":"SoundboardWeb.Endpoint.unsubscribe/1","doc":"Callback implementation for  Phoenix.Endpoint.unsubscribe/1 .","ref":"SoundboardWeb.Endpoint.html#unsubscribe/1"},{"type":"function","title":"SoundboardWeb.Endpoint.url/0","doc":"Generates the endpoint base URL without any path information.\n\nIt uses the configuration under `:url` to generate such.","ref":"SoundboardWeb.Endpoint.html#url/0"},{"type":"module","title":"SoundboardWeb.ErrorHTML","doc":"Renders fallback HTML error messages.","ref":"SoundboardWeb.ErrorHTML.html"},{"type":"function","title":"SoundboardWeb.ErrorHTML.render/2","doc":"","ref":"SoundboardWeb.ErrorHTML.html#render/2"},{"type":"module","title":"SoundboardWeb.ErrorJSON","doc":"Renders fallback JSON error payloads.","ref":"SoundboardWeb.ErrorJSON.html"},{"type":"function","title":"SoundboardWeb.ErrorJSON.render/2","doc":"","ref":"SoundboardWeb.ErrorJSON.html#render/2"},{"type":"module","title":"SoundboardWeb.FavoritesLive","doc":"","ref":"SoundboardWeb.FavoritesLive.html"},{"type":"function","title":"SoundboardWeb.FavoritesLive.mount_presence/2","doc":"","ref":"SoundboardWeb.FavoritesLive.html#mount_presence/2"},{"type":"function","title":"SoundboardWeb.FavoritesLive.render/1","doc":"Callback implementation for  Phoenix.LiveView.render/1 .","ref":"SoundboardWeb.FavoritesLive.html#render/1"},{"type":"module","title":"SoundboardWeb.Gettext","doc":"A module providing Internationalization with a gettext-based API.\n\nBy using [Gettext](https://hexdocs.pm/gettext), your module compiles translations\nthat you can use in your application. To use this Gettext backend module,\ncall `use Gettext` and pass it as an option:\n\n    use Gettext, backend: SoundboardWeb.Gettext\n\n    # Simple translation\n    gettext(\"Here is the string to translate\")\n\n    # Plural translation\n    ngettext(\"Here is the string to translate\",\n             \"Here are the strings to translate\",\n             3)\n\n    # Domain-based translation\n    dgettext(\"errors\", \"Here is the error message to translate\")\n\nSee the [Gettext Docs](https://hexdocs.pm/gettext) for detailed usage.","ref":"SoundboardWeb.Gettext.html"},{"type":"function","title":"SoundboardWeb.Gettext.handle_missing_bindings/2","doc":"Callback implementation for  Gettext.Backend.handle_missing_bindings/2 .","ref":"SoundboardWeb.Gettext.html#handle_missing_bindings/2"},{"type":"function","title":"SoundboardWeb.Gettext.handle_missing_plural_translation/7","doc":"Callback implementation for  Gettext.Backend.handle_missing_plural_translation/7 .","ref":"SoundboardWeb.Gettext.html#handle_missing_plural_translation/7"},{"type":"function","title":"SoundboardWeb.Gettext.handle_missing_translation/5","doc":"Callback implementation for  Gettext.Backend.handle_missing_translation/5 .","ref":"SoundboardWeb.Gettext.html#handle_missing_translation/5"},{"type":"module","title":"SoundboardWeb.GuildController","doc":"Tenant onboarding: list the guilds the shared bot is a member of and let the\nsigned-in user switch their active soundboard (creating the tenant row on\nfirst use — that is the whole \"provisioning\" step).\n\nWith billing configured, switching to a guild without an active\nsubscription goes to checkout instead, remembering the guild: the Stripe\nwebhook is the only hosted provisioning path, so no tenant row is created\nhere.\n\nOnly members of a Discord guild may switch to it or open it by slug, and\nonly its owner may claim its slug (`Soundboard.Tenants.Membership`).","ref":"SoundboardWeb.GuildController.html"},{"type":"function","title":"SoundboardWeb.GuildController.claim/2","doc":"Claims a slug (subdomain name) for the session's current guild.\n\nAvailability is pre-checked with `Tenants.slug_available?/1` for a clean\nerror path; reserved/duplicate slugs are rejected authoritatively inside\n`Tenants.claim_slug/2`.","ref":"SoundboardWeb.GuildController.html#claim/2"},{"type":"function","title":"SoundboardWeb.GuildController.index/2","doc":"","ref":"SoundboardWeb.GuildController.html#index/2"},{"type":"function","title":"SoundboardWeb.GuildController.show/2","doc":"Scopes the app to the tenant resolved by slug. Resolution never creates a\nrow: an unknown slug is a 404. Setting the session `:guild_id` is what makes\nthe Tenant plug (and LiveViews on subsequent requests) pick the guild up.","ref":"SoundboardWeb.GuildController.html#show/2"},{"type":"function","title":"SoundboardWeb.GuildController.switch/2","doc":"","ref":"SoundboardWeb.GuildController.html#switch/2"},{"type":"module","title":"SoundboardWeb.Live.Support.LiveTags","doc":"LiveView-facing tag queries and mutations for the soundboard.","ref":"SoundboardWeb.Live.Support.LiveTags.html"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.add_tag/3","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#add_tag/3"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.all_tags/1","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#all_tags/1"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.broadcast_update/0","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#broadcast_update/0"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.count_sounds_with_tag/2","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#count_sounds_with_tag/2"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.search/1","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#search/1"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.tag_selected?/2","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#tag_selected?/2"},{"type":"function","title":"SoundboardWeb.Live.Support.LiveTags.update_sound_tags/2","doc":"","ref":"SoundboardWeb.Live.Support.LiveTags.html#update_sound_tags/2"},{"type":"module","title":"SoundboardWeb.Live.Support.PresenceLive","doc":"","ref":"SoundboardWeb.Live.Support.PresenceLive.html"},{"type":"module","title":"SoundboardWeb.OnboardingController","doc":"The onboarding handoff for hosted signups. A signed-in user invites the\nshared bot from here, then continues to `/guilds` where switching\nprovisions the tenant.","ref":"SoundboardWeb.OnboardingController.html"},{"type":"function","title":"SoundboardWeb.OnboardingController.show/2","doc":"","ref":"SoundboardWeb.OnboardingController.html#show/2"},{"type":"module","title":"SoundboardWeb.Plugs.APIAuth","doc":"API authentication plug.","ref":"SoundboardWeb.Plugs.APIAuth.html"},{"type":"function","title":"SoundboardWeb.Plugs.APIAuth.call/2","doc":"","ref":"SoundboardWeb.Plugs.APIAuth.html#call/2"},{"type":"function","title":"SoundboardWeb.Plugs.APIAuth.init/1","doc":"","ref":"SoundboardWeb.Plugs.APIAuth.html#init/1"},{"type":"module","title":"SoundboardWeb.Plugs.AppGate","doc":"Gate for the soundboard app pages (Sounds, Stats, Favorites, Settings).\n\nSelf-hosted (billing dormant) everything is unlocked — the pre-billing\nbehavior is unchanged. On hosted, a signed-in user must have picked a guild\nwhose tenant row carries an active subscription before they can use the app;\notherwise they are steered to `/guilds` (pick a soundboard) or `/billing`\n(subscribe). Setup pages (/guilds, /onboarding, /billing) are never gated —\nthey are the path to getting unlocked.\n\nRuns after `SoundboardWeb.Plugs.Tenant`, so the guild is the resolved\n`:current_guild_id`; a picked soundboard is one with a tenant row\n(`:current_guild` is a `Soundboard.Tenants.Guild`).\n\nAlso assigns `:app_unlocked` so the navbar can hide app navigation until the\ngate opens.","ref":"SoundboardWeb.Plugs.AppGate.html"},{"type":"function","title":"SoundboardWeb.Plugs.AppGate.call/2","doc":"Runs in :auth (assign only) and again in :app_access (gate + redirect).","ref":"SoundboardWeb.Plugs.AppGate.html#call/2"},{"type":"function","title":"SoundboardWeb.Plugs.AppGate.init/1","doc":"","ref":"SoundboardWeb.Plugs.AppGate.html#init/1"},{"type":"module","title":"SoundboardWeb.Plugs.BasicAuth","doc":"Basic authentication plug.\n\nWhen both `BASIC_AUTH_USERNAME` and `BASIC_AUTH_PASSWORD` environment variables\nare set to non-blank values, every browser request must supply matching Basic\ncredentials. When either variable is missing or blank, basic auth is disabled\nand all requests pass through.","ref":"SoundboardWeb.Plugs.BasicAuth.html"},{"type":"function","title":"SoundboardWeb.Plugs.BasicAuth.call/2","doc":"","ref":"SoundboardWeb.Plugs.BasicAuth.html#call/2"},{"type":"function","title":"SoundboardWeb.Plugs.BasicAuth.init/1","doc":"","ref":"SoundboardWeb.Plugs.BasicAuth.html#init/1"},{"type":"module","title":"SoundboardWeb.Plugs.RoleCheck","doc":"Re-checks a signed-in user's required Discord role at most every\n`:role_recheck_interval_seconds` (default 15 minutes), and signs them out\nwhen they no longer have it. Runs after `ensure_authenticated_user`, so\nthere is always a user.","ref":"SoundboardWeb.Plugs.RoleCheck.html"},{"type":"function","title":"SoundboardWeb.Plugs.RoleCheck.call/2","doc":"","ref":"SoundboardWeb.Plugs.RoleCheck.html#call/2"},{"type":"function","title":"SoundboardWeb.Plugs.RoleCheck.init/1","doc":"","ref":"SoundboardWeb.Plugs.RoleCheck.html#init/1"},{"type":"module","title":"SoundboardWeb.Plugs.Tenant","doc":"Resolves the current tenant (guild) for a request.\n\nResolution order:\n1. Subdomain — `{slug}.soundbored.app` (base host configured as\n   `:tenant_base_host`) must map to an existing guild slug, else 404.\n2. Session — `guild_id` set by the guild switcher.\n3. Default guild — keeps zero-config single-guild deployments unchanged.\n\nA signed-in user (browser session or API token) must be a member of the\nresolved guild (`Soundboard.Tenants.Membership`): a subdomain they are not\nin is a 403, and a session guild they are not in falls back to the default\nguild. Signed-out requests resolve normally; the routes that need a user\nredirect them to sign in afterwards.\n\nAssigns `:current_guild_id` (string) and `:current_guild` (row or nil), and\nmirrors the id into the session so LiveViews receive it on mount.","ref":"SoundboardWeb.Plugs.Tenant.html"},{"type":"function","title":"SoundboardWeb.Plugs.Tenant.call/2","doc":"","ref":"SoundboardWeb.Plugs.Tenant.html#call/2"},{"type":"function","title":"SoundboardWeb.Plugs.Tenant.init/1","doc":"","ref":"SoundboardWeb.Plugs.Tenant.html#init/1"},{"type":"module","title":"SoundboardWeb.Presence","doc":"The Presence module.","ref":"SoundboardWeb.Presence.html"},{"type":"function","title":"SoundboardWeb.Presence.child_spec/1","doc":"","ref":"SoundboardWeb.Presence.html#child_spec/1"},{"type":"function","title":"SoundboardWeb.Presence.fetch/2","doc":"Callback implementation for  Phoenix.Presence.fetch/2 .","ref":"SoundboardWeb.Presence.html#fetch/2"},{"type":"function","title":"SoundboardWeb.Presence.fetchers_pids/0","doc":"","ref":"SoundboardWeb.Presence.html#fetchers_pids/0"},{"type":"function","title":"SoundboardWeb.Presence.get_by_key/2","doc":"Callback implementation for  Phoenix.Presence.get_by_key/2 .","ref":"SoundboardWeb.Presence.html#get_by_key/2"},{"type":"function","title":"SoundboardWeb.Presence.list/1","doc":"Callback implementation for  Phoenix.Presence.list/1 .","ref":"SoundboardWeb.Presence.html#list/1"},{"type":"function","title":"SoundboardWeb.Presence.track/3","doc":"Callback implementation for  Phoenix.Presence.track/3 .","ref":"SoundboardWeb.Presence.html#track/3"},{"type":"function","title":"SoundboardWeb.Presence.track/4","doc":"Callback implementation for  Phoenix.Presence.track/4 .","ref":"SoundboardWeb.Presence.html#track/4"},{"type":"function","title":"SoundboardWeb.Presence.untrack/2","doc":"Callback implementation for  Phoenix.Presence.untrack/2 .","ref":"SoundboardWeb.Presence.html#untrack/2"},{"type":"function","title":"SoundboardWeb.Presence.untrack/3","doc":"Callback implementation for  Phoenix.Presence.untrack/3 .","ref":"SoundboardWeb.Presence.html#untrack/3"},{"type":"function","title":"SoundboardWeb.Presence.update/3","doc":"Callback implementation for  Phoenix.Presence.update/3 .","ref":"SoundboardWeb.Presence.html#update/3"},{"type":"function","title":"SoundboardWeb.Presence.update/4","doc":"Callback implementation for  Phoenix.Presence.update/4 .","ref":"SoundboardWeb.Presence.html#update/4"},{"type":"module","title":"SoundboardWeb.PresenceHandler","doc":"Handles presence tracking for the Soundboard app.","ref":"SoundboardWeb.PresenceHandler.html"},{"type":"function","title":"SoundboardWeb.PresenceHandler.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"SoundboardWeb.PresenceHandler.html#child_spec/1"},{"type":"function","title":"SoundboardWeb.PresenceHandler.get_user_color/1","doc":"","ref":"SoundboardWeb.PresenceHandler.html#get_user_color/1"},{"type":"function","title":"SoundboardWeb.PresenceHandler.start_link/1","doc":"","ref":"SoundboardWeb.PresenceHandler.html#start_link/1"},{"type":"module","title":"SoundboardWeb.RawBodyReader","doc":"A `Plug.Parsers` body_reader that keeps the untouched JSON request body in\n`conn.assigns[:raw_body]` (a list of chunks).\n\nStripe webhook signatures are computed over the raw bytes, and the JSON\nparser consumes the body before the controller runs, so the raw body must be\ncaptured during parsing. Only JSON bodies are cached — upload bodies go\nthrough the multipart parser and would otherwise be held in memory whole.","ref":"SoundboardWeb.RawBodyReader.html"},{"type":"function","title":"SoundboardWeb.RawBodyReader.read_body/2","doc":"","ref":"SoundboardWeb.RawBodyReader.html#read_body/2"},{"type":"module","title":"SoundboardWeb.Router","doc":"Routes. The app pages (Sounds, Stats, Favorites, Settings) need an active\nsubscription on hosted deployments (`:app_access`); self-hosted is always\nunlocked. Setup pages (pick a guild, claim a subdomain, subscribe) stay\nreachable while locked, since they are the way to unlock it; `:auth` only\ntells the navbar whether to show the app's links.\n\nController-rendered pages get the `@current_path` and `@presences` the app\nlayout reads from `assign_controller_defaults/2`; LiveViews assign their own.\n\nBilling routes are compiled in unless `:enable_billing` is false, and\n`:require_stripe` 404s them whenever `STRIPE_SECRET_KEY` is unset. The\nStripe webhook is public: its signature header is the credential, and it\ncarries no CSRF token.\n\n`/g/:slug` scopes the app to the tenant with that slug; a signed-out\nvisitor keeps the slug across sign-in (`:pending_slug`).","ref":"SoundboardWeb.Router.html"},{"type":"function","title":"SoundboardWeb.Router.api/2","doc":"","ref":"SoundboardWeb.Router.html#api/2"},{"type":"function","title":"SoundboardWeb.Router.app_access/2","doc":"","ref":"SoundboardWeb.Router.html#app_access/2"},{"type":"function","title":"SoundboardWeb.Router.assign_controller_defaults/2","doc":"","ref":"SoundboardWeb.Router.html#assign_controller_defaults/2"},{"type":"function","title":"SoundboardWeb.Router.auth/2","doc":"","ref":"SoundboardWeb.Router.html#auth/2"},{"type":"function","title":"SoundboardWeb.Router.auth_browser/2","doc":"","ref":"SoundboardWeb.Router.html#auth_browser/2"},{"type":"function","title":"SoundboardWeb.Router.browser/2","doc":"","ref":"SoundboardWeb.Router.html#browser/2"},{"type":"function","title":"SoundboardWeb.Router.call/2","doc":"Callback invoked by Plug on every request.","ref":"SoundboardWeb.Router.html#call/2"},{"type":"function","title":"SoundboardWeb.Router.ensure_authenticated_user/2","doc":"","ref":"SoundboardWeb.Router.html#ensure_authenticated_user/2"},{"type":"function","title":"SoundboardWeb.Router.fetch_current_user/2","doc":"","ref":"SoundboardWeb.Router.html#fetch_current_user/2"},{"type":"function","title":"SoundboardWeb.Router.formatted_routes/1","doc":"Callback implementation for  Phoenix.VerifiedRoutes.formatted_routes/1 .","ref":"SoundboardWeb.Router.html#formatted_routes/1"},{"type":"function","title":"SoundboardWeb.Router.init/1","doc":"Callback required by Plug that initializes the router\nfor serving web requests.","ref":"SoundboardWeb.Router.html#init/1"},{"type":"function","title":"SoundboardWeb.Router.remember_pending_slug/2","doc":"","ref":"SoundboardWeb.Router.html#remember_pending_slug/2"},{"type":"function","title":"SoundboardWeb.Router.require_browser_basic_auth/2","doc":"","ref":"SoundboardWeb.Router.html#require_browser_basic_auth/2"},{"type":"function","title":"SoundboardWeb.Router.require_role_check/2","doc":"","ref":"SoundboardWeb.Router.html#require_role_check/2"},{"type":"function","title":"SoundboardWeb.Router.require_stripe/2","doc":"","ref":"SoundboardWeb.Router.html#require_stripe/2"},{"type":"function","title":"SoundboardWeb.Router.stripe_webhook/2","doc":"","ref":"SoundboardWeb.Router.html#stripe_webhook/2"},{"type":"function","title":"SoundboardWeb.Router.verified_route?/2","doc":"Callback implementation for  Phoenix.VerifiedRoutes.verified_route?/2 .","ref":"SoundboardWeb.Router.html#verified_route?/2"},{"type":"module","title":"SoundboardWeb.SettingsLive","doc":"API tokens and their docs, and, on hosted deployments, the guild's plan:\nshown only when billing is configured and the signed-in user is the\nDiscord account that provisioned the guild.","ref":"SoundboardWeb.SettingsLive.html"},{"type":"function","title":"SoundboardWeb.SettingsLive.mount_presence/2","doc":"","ref":"SoundboardWeb.SettingsLive.html#mount_presence/2"},{"type":"function","title":"SoundboardWeb.SettingsLive.render/1","doc":"Callback implementation for  Phoenix.LiveView.render/1 .","ref":"SoundboardWeb.SettingsLive.html#render/1"},{"type":"module","title":"SoundboardWeb.SoundHelpers","doc":"Shared helpers for formatting sound metadata for UI rendering.","ref":"SoundboardWeb.SoundHelpers.html"},{"type":"function","title":"SoundboardWeb.SoundHelpers.display_name/1","doc":"","ref":"SoundboardWeb.SoundHelpers.html#display_name/1"},{"type":"function","title":"SoundboardWeb.SoundHelpers.slugify/1","doc":"","ref":"SoundboardWeb.SoundHelpers.html#slugify/1"},{"type":"module","title":"SoundboardWeb.Soundboard.SoundFilter","doc":"Filters sounds based on the selected tags and search query.","ref":"SoundboardWeb.Soundboard.SoundFilter.html"},{"type":"function","title":"SoundboardWeb.Soundboard.SoundFilter.filter_sounds/3","doc":"","ref":"SoundboardWeb.Soundboard.SoundFilter.html#filter_sounds/3"},{"type":"module","title":"SoundboardWeb.SoundboardLive","doc":"","ref":"SoundboardWeb.SoundboardLive.html"},{"type":"function","title":"SoundboardWeb.SoundboardLive.mount_presence/2","doc":"","ref":"SoundboardWeb.SoundboardLive.html#mount_presence/2"},{"type":"function","title":"SoundboardWeb.SoundboardLive.render/1","doc":"Callback implementation for  Phoenix.LiveView.render/1 .","ref":"SoundboardWeb.SoundboardLive.html#render/1"},{"type":"module","title":"SoundboardWeb.StatsLive","doc":"","ref":"SoundboardWeb.StatsLive.html"},{"type":"function","title":"SoundboardWeb.StatsLive.mount_presence/2","doc":"","ref":"SoundboardWeb.StatsLive.html#mount_presence/2"},{"type":"function","title":"SoundboardWeb.StatsLive.render/1","doc":"Callback implementation for  Phoenix.LiveView.render/1 .","ref":"SoundboardWeb.StatsLive.html#render/1"},{"type":"module","title":"SoundboardWeb.Telemetry","doc":"","ref":"SoundboardWeb.Telemetry.html"},{"type":"function","title":"SoundboardWeb.Telemetry.child_spec/1","doc":"Returns a specification to start this module under a supervisor.\n\nSee `Supervisor`.","ref":"SoundboardWeb.Telemetry.html#child_spec/1"},{"type":"function","title":"SoundboardWeb.Telemetry.metrics/0","doc":"","ref":"SoundboardWeb.Telemetry.html#metrics/0"},{"type":"function","title":"SoundboardWeb.Telemetry.start_link/1","doc":"","ref":"SoundboardWeb.Telemetry.html#start_link/1"},{"type":"module","title":"SoundboardWeb.UploadController","doc":"Serves uploaded sound files to the signed-in user, for the browser's local\npreview. Only the stored file of a sound in the current soundboard is\nserved; any other path, including another guild's sound, is a 404.","ref":"SoundboardWeb.UploadController.html"},{"type":"function","title":"SoundboardWeb.UploadController.show/2","doc":"","ref":"SoundboardWeb.UploadController.html#show/2"}],"proglang":"elixir","content_type":"text/markdown","producer":{"name":"ex_doc","version":"0.40.3"}}